  );
  const [showFilters, setShowFilters] = useState(false);
  const [filters, setFilters] = useState<SearchFilters>({
    name: "",
    sku: "",
    barcode: "",
    minPrice: "",
    maxPrice: "",
    inStockOnly: false,
    lowStockOnly: false,
  });
  const { accessToken, user } = useAuthStore();
  const debounceTimerRef = useRef<NodeJS.Timeout | null>(null);

  // Apply filters to products
  useEffect(() => {
    // First, deduplicate products by name (keep first occurrence)
    const seenNames = new Set<string>();
    const uniqueProducts = products.filter((product) => {
      const nameLower = product.name.toLowerCase().trim();
      if (seenNames.has(nameLower)) {
        return false;
      }
      seenNames.add(nameLower);
      return true;
    });

    let filtered = [...uniqueProducts];

    // Apply text search query (searches name, SKU, and barcode)
    if (searchQuery.trim()) {
      const query = searchQuery.toLowerCase();
      filtered = filtered.filter((product) => {
        const nameMatch = product.name.toLowerCase().includes(query);
        const skuMatch = product.sku.toLowerCase().includes(query);
        const barcodeMatch = product.barcode?.toLowerCase().includes(query);
        return nameMatch || skuMatch || barcodeMatch;
      });
    }

    // Apply advanced filters
    if (filters.name) {
      const nameQuery = filters.name.toLowerCase();
      filtered = filtered.filter((p) =>
        p.name.toLowerCase().includes(nameQuery),
      );
    }

    if (filters.sku) {
      const skuQuery = filters.sku.toLowerCase();
      filtered = filtered.filter((p) => p.sku.toLowerCase().includes(skuQuery));
    }

    if (filters.barcode) {
      const barcodeQuery = filters.barcode.toLowerCase();
      filtered = filtered.filter((p) =>
        p.barcode?.toLowerCase().includes(barcodeQuery),
      );
    }

    if (filters.minPrice) {
      const minPrice = parseFloat(filters.minPrice) * 100; // Convert to cents
      filtered = filtered.filter((p) => p.priceCents >= minPrice);
    }

    if (filters.maxPrice) {
      const maxPrice = parseFloat(filters.maxPrice) * 100; // Convert to cents
      filtered = filtered.filter((p) => p.priceCents <= maxPrice);
    }

    if (filters.inStockOnly) {
      filtered = filtered.filter((p) => p.stock !== undefined && p.stock > 0);
    }

    if (filters.lowStockOnly) {
      filtered = filtered.filter(
        (p) => p.stock !== undefined && p.stock > 0 && p.stock < 10,
      );
    }

    setFilteredProducts(filtered);
  }, [products, searchQuery, filters]);

  // Debounced search - wait 300ms after user stops typing
  useEffect(() => {
    if (!accessToken) return;

    // Clear existing timer
    if (debounceTimerRef.current) {
      clearTimeout(debounceTimerRef.current);
    }

    // Set new timer
    debounceTimerRef.current = setTimeout(() => {
      if (searchQuery.trim()) {
        searchProducts(searchQuery);
      } else {
        // Load all products when search is empty
        loadAllProducts();
      }
    }, 300); // 300ms debounce delay

    // Cleanup
    return () => {
      if (debounceTimerRef.current) {
        clearTimeout(debounceTimerRef.current);
      }
    };
  }, [searchQuery, accessToken]);

  // Load stock levels for products
  const loadStockLevels = async (
    productList: Product[],
  ): Promise<ProductWithStock[]> => {
    if (!user?.locationId || !accessToken) {
      return productList.map((p) => ({ ...p, stock: undefined }));
    }

    try {
      const stockResponse = await axios.get(
        `${API_URL}/api/v1/inventory/${user.locationId}/stock`,
        {
          headers: { Authorization: `Bearer ${accessToken}` },
        },
      );
      const stockMap = new Map<string, number>(
        (stockResponse.data || []).map((item: any) => [
          item.productId,
          item.quantity,
        ]),
      );
      return productList.map((product) => ({
        ...product,
        stock: stockMap.get(product.id) as number | undefined,
      }));
    } catch (error) {
      console.warn("Failed to load stock levels:", error);
      return productList.map((p) => ({ ...p, stock: undefined }));
    }
  };

  const searchProducts = async (query: string) => {
    if (!accessToken) {
      console.warn("No access token available");
      return;
    }

    setLoading(true);
    try {
      const response = await axios.get(
        `${API_URL}/api/v1/products?query=${encodeURIComponent(query)}`,
      );
      const productList = response.data || [];
      const productsWithStock = await loadStockLevels(productList);
      setProducts(productsWithStock);
    } catch (error) {
      console.error("Failed to search products:", error);
      setProducts([]);
    } finally {
      setLoading(false);
    }
  };

  const loadAllProducts = async () => {
    if (!accessToken) {
      console.warn("No access token available");
      return;
    }

    setLoading(true);
    try {
      const response = await axios.get(`${API_URL}/api/v1/products`);
      const productList = (response.data || []).slice(0, 20);
      const productsWithStock = await loadStockLevels(productList);
      setProducts(productsWithStock);
    } catch (error) {
      console.error("Failed to load products:", error);
      setProducts([]);
    } finally {
      setLoading(false);
    }
  };

  // Load recently scanned products from localStorage
  useEffect(() => {
    const recent = localStorage.getItem("recentlyScanned");
    if (recent) {
      try {
        const recentProducts = JSON.parse(recent) as Product[];
        loadStockLevels(recentProducts).then(setRecentlyScanned);
      } catch (error) {
        console.warn("Failed to load recently scanned:", error);
      }
    }
  }, []);

  // Save to recently scanned when product is added
  const saveToRecentlyScanned = (product: Product) => {
    const recent = localStorage.getItem("recentlyScanned");
    let recentProducts: Product[] = recent ? JSON.parse(recent) : [];

    // Remove if already exists
    recentProducts = recentProducts.filter((p) => p.id !== product.id);

    // Add to beginning
    recentProducts.unshift(product);

    // Keep only last 10
    recentProducts = recentProducts.slice(0, 10);

    localStorage.setItem("recentlyScanned", JSON.stringify(recentProducts));
    loadStockLevels(recentProducts).then(setRecentlyScanned);
  };

  const handleProductClick = async (product: ProductWithStock) => {
    // Validate product ID format (must be UUID)
    const uuidRegex =
      /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
    if (!uuidRegex.test(product.id)) {
      console.error(
        `Invalid productId format: ${product.id} for product: ${product.name}`,
      );
      toast.error(
        `Invalid product ID for "${product.name}". This product needs to be recreated.`,
      );
      return;
    }

    // Check stock before opening quantity selector
    if (product.stock !== undefined && product.stock <= 0) {
      toast.error(`${product.name} is out of stock`);
      return;
    }

    // Open quantity selector modal
    if (onSelectProduct) {
      onSelectProduct(product);
    } else {
      // Fallback: directly add with quantity 1
      onAddToCart({
        productId: product.id,
        name: product.name,
        priceCents: product.priceCents,
        taxRate: product.taxRate,
        quantity: 1,
      });
      saveToRecentlyScanned(product);
      toast.success(
        `Added: ${product.name}${product.stock !== undefined ? ` (${product.stock} in stock)` : ""}`,
      );
    }
  };

  const handleBarcodeInput = (e: React.KeyboardEvent<HTMLInputElement>) => {
    // If Enter is pressed and input looks like a barcode (numeric/alphanumeric, 4+ chars)
    if (e.key === "Enter" && searchQuery.trim().length >= 4) {
      e.preventDefault();
      // Try to find product by barcode first
      const barcodeMatch = filteredProducts.find(
        (p) => p.barcode?.toLowerCase() === searchQuery.trim().toLowerCase(),
      );

      if (barcodeMatch) {
        handleProductClick(barcodeMatch);
        setSearchQuery("");
      } else {
        // If not found, show message
        toast.error(`Product with barcode "${searchQuery.trim()}" not found`);
      }
    }
  };

  const clearFilters = () => {
    setFilters({
      name: "",
      sku: "",
      barcode: "",
      minPrice: "",
      maxPrice: "",
      inStockOnly: false,
      lowStockOnly: false,
    });
  };

  const hasActiveFilters = () => {
    return Object.values(filters).some((value) => {
      if (typeof value === "boolean") return value;
      return value.trim() !== "";
    });
  };

  const getStockStatus = (stock: number | undefined) => {
    if (stock === undefined) return null;
    if (stock === 0)
      return {
        label: "Out of Stock",
        color: "text-rose-400 bg-rose-500/15 border-rose-400/40",
      };
    if (stock < 10)
      return {
        label: `Low Stock (${stock})`,
        color: "text-amber-400 bg-amber-500/15 border-amber-400/40",
      };
    return {
      label: `In Stock (${stock})`,
      color: "text-emerald-400 bg-emerald-500/15 border-emerald-400/40",
    };
  };

  return (
    <div className="space-y-6">
      {/* Search Input */}
      <div className="theme-card rounded-3xl border p-1.5 backdrop-blur-xl">
        <div className="theme-surface flex items-center gap-3 rounded-3xl px-4 py-3">
          <span className="theme-text-secondary text-lg">🔍</span>
          <input
            ref={searchInputRef}
            type="text"
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            onKeyDown={handleBarcodeInput}
            placeholder="Type product name, SKU, or barcode... Press Enter to add (F1 to focus)"
            className="flex-1 bg-transparent text-lg theme-text-primary placeholder:text-current/50 focus:outline-none font-medium"
            aria-label="Search products"
            aria-describedby="search-help"
            role="searchbox"
            autoComplete="off"
          />
          <span id="search-help" className="sr-only">
            Press F1 to focus this search box. Type to search for products by
            name, SKU, or barcode. Press Enter to add product.
          </span>
          <div className="flex items-center gap-2">
            <button
              onClick={() => setShowFilters(!showFilters)}
              className={`theme-chip rounded-full border px-3 py-1.5 text-xs font-semibold transition ${
                showFilters || hasActiveFilters()
                  ? "border-sky-400/40 bg-sky-500/15 text-sky-200"
                  : ""
              }`}
              title="Toggle advanced filters"
            >
              🔧 Filters {hasActiveFilters() && "•"}
            </button>
            {searchQuery && (
              <button
                onClick={() => setSearchQuery("")}
                className="theme-chip rounded-full border px-3 py-1.5 text-xs font-semibold transition"
              >
                Clear
              </button>
            )}
          </div>
        </div>
      </div>

      {/* Advanced Filters */}
      {showFilters && (
        <div className="theme-card rounded-3xl border p-6 backdrop-blur-xl">
          <div className="flex items-center justify-between mb-4">
            <h3 className="theme-text-primary text-lg font-semibold">
              Advanced Filters
            </h3>
            {hasActiveFilters() && (
              <button
                onClick={clearFilters}
                className="theme-chip rounded-full border border-rose-400/40 bg-rose-500/15 px-3 py-1.5 text-xs font-semibold text-rose-200 transition hover:bg-rose-500/25"
              >
                Clear All
              </button>
            )}
          </div>
          <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
            <div>
              <label className="block text-sm font-medium theme-text-secondary mb-1">
                Product Name
              </label>
              <input
                type="text"
                value={filters.name}
                onChange={(e) =>
                  setFilters({ ...filters, name: e.target.value })
                }
                placeholder="Filter by name..."
                className="w-full theme-surface rounded-lg border border-white/20 bg-transparent px-3 py-2 text-sm theme-text-primary placeholder:text-current/50 focus:border-sky-400 focus:outline-none"
              />
            </div>
            <div>
              <label className="block text-sm font-medium theme-text-secondary mb-1">
                SKU
              </label>
              <input
                type="text"
                value={filters.sku}
                onChange={(e) =>
                  setFilters({ ...filters, sku: e.target.value })
                }
                placeholder="Filter by SKU..."
                className="w-full theme-surface rounded-lg border border-white/20 bg-transparent px-3 py-2 text-sm theme-text-primary placeholder:text-current/50 focus:border-sky-400 focus:outline-none"
              />
            </div>
            <div>
              <label className="block text-sm font-medium theme-text-secondary mb-1">
                Barcode
              </label>
              <input
                type="text"
                value={filters.barcode}
                onChange={(e) =>
                  setFilters({ ...filters, barcode: e.target.value })
                }
                placeholder="Filter by barcode..."
                className="w-full theme-surface rounded-lg border border-white/20 bg-transparent px-3 py-2 text-sm theme-text-primary placeholder:text-current/50 focus:border-sky-400 focus:outline-none"
              />
            </div>
            <div>
              <label className="block text-sm font-medium theme-text-secondary mb-1">
                Min Price (₦)
              </label>
              <input
                type="number"
                step="0.01"
                value={filters.minPrice}
                onChange={(e) =>
                  setFilters({ ...filters, minPrice: e.target.value })
                }
                placeholder="0.00"
                className="w-full theme-surface rounded-lg border border-white/20 bg-transparent px-3 py-2 text-sm theme-text-primary placeholder:text-current/50 focus:border-sky-400 focus:outline-none"
              />
            </div>
            <div>
              <label className="block text-sm font-medium theme-text-secondary mb-1">
                Max Price (₦)
              </label>
              <input
                type="number"
                step="0.01"
                value={filters.maxPrice}
                onChange={(e) =>
                  setFilters({ ...filters, maxPrice: e.target.value })
                }
                placeholder="999999.99"
                className="w-full theme-surface rounded-lg border border-white/20 bg-transparent px-3 py-2 text-sm theme-text-primary placeholder:text-current/50 focus:border-sky-400 focus:outline-none"
              />
            </div>
            <div className="flex flex-col gap-2">
              <label className="block text-sm font-medium theme-text-secondary">
                Stock Filters
              </label>
              <label className="flex items-center gap-2 cursor-pointer">
                <input
                  type="checkbox"
                  checked={filters.inStockOnly}
                  onChange={(e) =>
                    setFilters({ ...filters, inStockOnly: e.target.checked })
                  }
                  className="rounded border-white/20 bg-transparent text-sky-400 focus:ring-sky-400"
                />
                <span className="text-sm theme-text-secondary">
                  In Stock Only
                </span>
              </label>
              <label className="flex items-center gap-2 cursor-pointer">
                <input
                  type="checkbox"
                  checked={filters.lowStockOnly}
                  onChange={(e) =>
                    setFilters({ ...filters, lowStockOnly: e.target.checked })
                  }
                  className="rounded border-white/20 bg-transparent text-sky-400 focus:ring-sky-400"
                />
                <span className="text-sm theme-text-secondary">
                  Low Stock Only (&lt;10)
                </span>
              </label>
            </div>
          </div>
          {filteredProducts.length !== products.length && (
            <div className="mt-4 text-sm theme-text-secondary">
              Showing {filteredProducts.length} of {products.length} products
            </div>
          )}
        </div>
      )}

      {/* Products Grid */}
      {loading ? (
        <div className="theme-card flex flex-col items-center justify-center rounded-3xl border p-12 text-center">
          <div className="h-12 w-12 animate-spin rounded-full border-2 border-slate-700 border-t-sky-400" />
          <p className="theme-text-secondary mt-5 text-sm uppercase tracking-[0.3em]">
            Loading
          </p>
        </div>
      ) : filteredProducts.length === 0 ? (
        <div className="theme-card rounded-3xl border p-10 text-center">
          <p className="theme-text-primary text-lg font-semibold">
            No products found
          </p>
          <p className="theme-text-secondary mt-2 text-sm">
            Try a different keyword or scan a barcode to identify products
            instantly.
          </p>
        </div>
      ) : (
        <>
          {/* Recently Scanned Section */}
          {recentlyScanned.length > 0 && !searchQuery && (
            <div className="space-y-3">
              <h3 className="theme-text-primary text-sm font-semibold uppercase tracking-wider">
                Recently Scanned
              </h3>
              <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">
                {recentlyScanned.slice(0, 4).map((product) => (
                  <div
                    key={product.id}
                    className="theme-surface group relative overflow-hidden rounded-2xl border p-4 shadow transition hover:-translate-y-1"
                  >
                    {product.images && product.images[0] && (
                      <div className="mb-3 aspect-square w-full overflow-hidden rounded-xl bg-slate-800">
                        <img
                          src={product.images[0]}
                          alt={product.name}
                          className="h-full w-full object-cover"
                          onError={(e) => {
                            (e.target as HTMLImageElement).style.display =
                              "none";
                          }}
                        />
                      </div>
                    )}
                    <h4 className="theme-text-primary line-clamp-1 text-sm font-semibold">
                      {product.name}
                    </h4>
                    <p className="theme-text-secondary mt-1 text-xs">
                      {formatCurrency(product.priceCents)}
                    </p>
                    {getStockStatus(product.stock) && (
                      <span
                        className={`mt-2 inline-block rounded-full border px-2 py-0.5 text-[0.65rem] font-medium ${getStockStatus(product.stock)?.color}`}
                      >
                        {getStockStatus(product.stock)?.label}
                      </span>
                    )}
                    <div className="flex gap-2">
                      {onPriceOverride && (
                        <button
                          onClick={() => onPriceOverride(product)}
                          className="mt-3 flex-1 rounded-lg border border-amber-400/40 bg-amber-500/15 px-2 py-2 text-xs font-semibold text-amber-200 transition hover:bg-amber-500/25"
                          title="Override price (requires manager PIN)"
                        >
                          Override
                        </button>
                      )}
                      <button
                        onClick={() => handleProductClick(product)}
                        className="mt-3 flex-1 rounded-lg bg-gradient-to-r from-sky-400 to-blue-500 px-3 py-2 text-xs font-semibold text-white transition hover:scale-105 active:scale-95"
                        disabled={product.stock === 0}
                      >
                        Select
                      </button>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* Products Table */}
          <div className="theme-card rounded-3xl border overflow-hidden backdrop-blur-xl">
            <div className="overflow-x-auto">
              <table className="w-full">
                <thead>
                  <tr className="border-b border-white/10">
                    <th className="px-6 py-4 text-left text-xs font-semibold uppercase tracking-wider theme-text-secondary">
                      SKU
                    </th>
                    <th className="px-6 py-4 text-left text-xs font-semibold uppercase tracking-wider theme-text-secondary">
                      Product Name
                    </th>
                    <th className="px-6 py-4 text-left text-xs font-semibold uppercase tracking-wider theme-text-secondary">
                      Price
                    </th>
                    <th className="px-6 py-4 text-left text-xs font-semibold uppercase tracking-wider theme-text-secondary">
                      VAT
                    </th>
                    <th className="px-6 py-4 text-left text-xs font-semibold uppercase tracking-wider theme-text-secondary">
                      Stock
                    </th>
                    <th className="px-6 py-4 text-center text-xs font-semibold uppercase tracking-wider theme-text-secondary">
                      Quantity
                    </th>
                    <th className="px-6 py-4 text-right text-xs font-semibold uppercase tracking-wider theme-text-secondary">
                      Actions
                    </th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-white/10">
                  {filteredProducts.map((product) => {
                    const stockStatus = getStockStatus(product.stock);
                    const cartItem = cartItems.find(
                      (item) => item.productId === product.id,
                    );
                    const quantity = cartItem?.quantity || 0;
                    const isInCart = quantity > 0;
                    const hasDiscount =
                      cartItem?.discountCents && cartItem.discountCents > 0;

                    return (
                      <tr
                        key={product.id}
                        className={`hover:bg-white/5 transition ${isInCart ? "bg-sky-500/5" : ""}`}
                      >
                        <td className="px-6 py-4 whitespace-nowrap">
                          <span className="theme-text-secondary text-sm font-mono">
                            {product.sku}
                          </span>
                        </td>
                        <td className="px-6 py-4">
                          <div className="flex items-center gap-3">
                            {product.images && product.images[0] && (
                              <div className="h-12 w-12 flex-shrink-0 overflow-hidden rounded-lg bg-slate-800">
                                <img
                                  src={product.images[0]}
                                  alt={product.name}
                                  className="h-full w-full object-cover"
                                  onError={(e) => {
                                    (
                                      e.target as HTMLImageElement
                                    ).style.display = "none";
                                  }}
                                />
                              </div>
                            )}
                            <span className="theme-text-primary font-medium">
                              {product.name}
                            </span>
                          </div>
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap">
                          <span className="text-lg font-semibold text-sky-400">
                            {formatCurrency(product.priceCents)}
                          </span>
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap">
                          <span className="theme-chip rounded-full border px-2.5 py-1 text-xs font-medium">
                            {(product.taxRate * 100).toFixed(1)}%
                          </span>
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap">
                          {stockStatus ? (
                            <span
                              className={`rounded-full border px-3 py-1 text-xs font-semibold ${stockStatus.color}`}
                            >
                              {stockStatus.label}
                            </span>
                          ) : (
                            <span className="theme-text-secondary text-sm">
                              —
                            </span>
                          )}
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap">
                          <div className="flex items-center justify-center gap-2">
                            {isInCart ? (
                              <>
                                <button
                                  onClick={() =>
                                    onUpdateQuantity &&
                                    onUpdateQuantity(
                                      product.id,
                                      Math.max(0, quantity - 1),
                                    )
                                  }
                                  className="theme-chip flex h-10 w-10 items-center justify-center rounded-full border text-lg font-semibold transition hover:border-white/30 hover:bg-white/20 touch-manipulation"
                                  aria-label="Decrease quantity"
                                >
                                  −
                                </button>
                                <input
                                  type="number"
                                  min="0"
                                  value={quantity}
                                  onChange={(e) => {
                                    const newQty =
                                      parseInt(e.target.value) || 0;
                                    if (onUpdateQuantity) {
                                      onUpdateQuantity(product.id, newQty);
                                    }
                                  }}
                                  className="w-16 text-center theme-surface rounded-lg border border-white/20 bg-transparent px-2 py-2 text-base font-semibold theme-text-primary focus:border-sky-400 focus:outline-none"
                                />
                                <button
                                  onClick={() =>
                                    onUpdateQuantity &&
                                    onUpdateQuantity(product.id, quantity + 1)
                                  }
                                  disabled={
                                    product.stock !== undefined &&
                                    quantity >= product.stock
                                  }
                                  className="theme-chip flex h-10 w-10 items-center justify-center rounded-full border text-lg font-semibold transition hover:border-white/30 hover:bg-white/20 disabled:opacity-50 disabled:cursor-not-allowed touch-manipulation"
                                  aria-label="Increase quantity"
                                >
                                  +
                                </button>
                              </>
                            ) : (
                              <button
                                onClick={() => {
                                  onAddToCart({
                                    productId: product.id,
                                    name: product.name,
                                    priceCents: product.priceCents,
                                    taxRate: product.taxRate,
                                    quantity: 1,
                                  });
                                  saveToRecentlyScanned(product);
                                  toast.success(`Added: ${product.name}`);
                                }}
                                disabled={product.stock === 0}
                                className="rounded-lg bg-gradient-to-r from-sky-400 via-blue-500 to-indigo-500 px-4 py-2 text-sm font-semibold text-white shadow-lg shadow-slate-900/40 transition hover:shadow-slate-900/60 hover:scale-105 active:scale-95 disabled:cursor-not-allowed disabled:opacity-50 disabled:hover:scale-100"
                              >
                                Add
                              </button>
                            )}
                          </div>
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap text-right">
                          <div className="flex items-center justify-end gap-2">
                            {isInCart && onItemDiscount && (
                              <button
                                onClick={() =>
                                  onItemDiscount({
                                    productId: product.id,
                                    name: product.name,
                                    priceCents: product.priceCents,
                                    quantity: quantity,
                                  })
                                }
                                className={`rounded-lg border px-3 py-2 text-xs font-semibold transition ${
                                  hasDiscount
                                    ? "border-emerald-400/40 bg-emerald-500/15 text-emerald-200"
                                    : "border-sky-400/40 bg-sky-500/15 text-sky-200"
                                }`}
                                title="Apply discount"
                              >
                                {hasDiscount ? "✓ Discount" : "Discount"}
                              </button>
                            )}
                            {onPriceOverride && (
                              <button
                                onClick={() => onPriceOverride(product)}
                                className="rounded-lg border border-amber-400/40 bg-amber-500/15 px-3 py-2 text-xs font-semibold text-amber-200 transition hover:bg-amber-500/25"
                                title="Override price (requires manager PIN)"
                              >
                                Override
                              </button>
                            )}
                            {isInCart && onRemoveFromCart && (
                              <button
                                onClick={() => onRemoveFromCart(product.id)}
                                className="rounded-lg border border-rose-400/40 bg-rose-500/15 px-3 py-2 text-xs font-semibold text-rose-200 transition hover:bg-rose-500/25"
                                title="Remove from cart"
                              >
                                Remove
                              </button>
                            )}
                          </div>
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          </div>
        </>
      )}
    </div>
  );
}

import { useState, useEffect, useRef } from "react";
import { formatCurrency, formatNumber } from "../utils/numberFormat";

interface Product {
  id: string;
  sku: string;
  name: string;
  priceCents: number;
  taxRate: number;
  stock?: number;
  images?: string[];
}

interface QuantitySelectorModalProps {
  isOpen: boolean;
  product: Product | null;
  onClose: () => void;
  onConfirm: (product: Product, quantity: number) => void;
}

export function QuantitySelectorModal({
  isOpen,
  product,
  onClose,
  onConfirm,
}: QuantitySelectorModalProps) {
  const [quantity, setQuantity] = useState(1);
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (isOpen && product) {
      setQuantity(1);
      // Focus input after modal opens
      setTimeout(() => {
        inputRef.current?.focus();
        inputRef.current?.select();
      }, 100);
    }
  }, [isOpen, product]);

  useEffect(() => {
    const handleEscape = (e: KeyboardEvent) => {
      if (e.key === "Escape" && isOpen) {
        onClose();
      }
    };

    const handleEnter = (e: KeyboardEvent) => {
      if (e.key === "Enter" && isOpen && product && quantity > 0) {
        handleConfirm();
      }
    };

    if (isOpen) {
      document.addEventListener("keydown", handleEscape);
      document.addEventListener("keydown", handleEnter);
    }

    return () => {
      document.removeEventListener("keydown", handleEscape);
      document.removeEventListener("keydown", handleEnter);
    };
  }, [isOpen, product, quantity, onClose]);

  if (!isOpen || !product) return null;

  const handleConfirm = () => {
    if (quantity > 0 && (!product.stock || quantity <= product.stock)) {
      onConfirm(product, quantity);
      onClose();
      setQuantity(1);
    }
  };

  const handleQuantityChange = (value: string) => {
    const numValue = parseInt(value, 10);
    if (!isNaN(numValue) && numValue >= 0) {
      if (product.stock !== undefined) {
        setQuantity(Math.min(numValue, product.stock));
      } else {
        setQuantity(numValue);
      }
    } else if (value === "") {
      setQuantity(0);
    }
  };

  const incrementQuantity = () => {
    if (product.stock !== undefined) {
      setQuantity((prev) => Math.min(prev + 1, product.stock!));
    } else {
      setQuantity((prev) => prev + 1);
    }
  };

  const decrementQuantity = () => {
    setQuantity((prev) => Math.max(prev - 1, 1));
  };

  const maxQuantity = product.stock ?? 9999;
  const canAdd = quantity > 0 && quantity <= maxQuantity;
  const isOutOfStock = product.stock !== undefined && product.stock === 0;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm p-4">
      <div className="theme-card w-full max-w-md animate-in fade-in zoom-in-95 rounded-3xl border p-6 shadow-2xl">
        {/* Product Info */}
        <div className="mb-6">
          {product.images && product.images[0] && (
            <div className="mb-4 aspect-square w-full overflow-hidden rounded-2xl bg-slate-800">
              <img
                src={product.images[0]}
                alt={product.name}
                className="h-full w-full object-cover"
                onError={(e) => {
                  (e.target as HTMLImageElement).style.display = "none";
                }}
              />
            </div>
          )}
          <h2 className="theme-text-primary text-2xl font-semibold">
            {product.name}
          </h2>
          <div className="mt-2 flex items-center justify-between">
            <div>
              <p className="theme-text-secondary text-sm">SKU: {product.sku}</p>
              <p className="theme-text-primary mt-1 text-xl font-semibold">
                {formatCurrency(product.priceCents)}
              </p>
            </div>
            <div className="text-right">
              {isOutOfStock ? (
                <span className="inline-block rounded-full border border-rose-400/40 bg-rose-500/15 px-3 py-1 text-xs font-medium text-rose-400">
                  Out of Stock
                </span>
              ) : product.stock !== undefined ? (
                <span className="inline-block rounded-full border border-emerald-400/40 bg-emerald-500/15 px-3 py-1 text-xs font-medium text-emerald-400">
                  {product.stock} in stock
                </span>
              ) : null}
            </div>
          </div>
        </div>

        {/* Quantity Selector */}
        <div className="mb-6">
          <label className="block text-sm font-medium theme-text-secondary mb-2">
            Quantity
          </label>
          <div className="flex items-center gap-3">
            <button
              onClick={decrementQuantity}
              disabled={quantity <= 1}
              className="flex h-12 w-12 items-center justify-center rounded-full border border-white/20 bg-white/5 text-xl font-semibold theme-text-primary transition hover:bg-white/10 disabled:opacity-50 disabled:cursor-not-allowed"
            >
              −
            </button>
            <input
              ref={inputRef}
              type="number"
              min="1"
              max={maxQuantity}
              value={quantity}
              onChange={(e) => handleQuantityChange(e.target.value)}
              className="flex-1 rounded-xl border border-white/20 bg-white/5 px-4 py-3 text-center text-2xl font-semibold theme-text-primary focus:border-sky-400 focus:outline-none focus:ring-2 focus:ring-sky-400/20"
              placeholder="0"
            />
            <button
              onClick={incrementQuantity}
              disabled={quantity >= maxQuantity || isOutOfStock}
              className="flex h-12 w-12 items-center justify-center rounded-full border border-white/20 bg-white/5 text-xl font-semibold theme-text-primary transition hover:bg-white/10 disabled:opacity-50 disabled:cursor-not-allowed"
            >
              +
            </button>
          </div>
          {product.stock !== undefined && quantity > product.stock && (
            <p className="mt-2 text-xs text-rose-400">
              Only {product.stock} available in stock
            </p>
          )}
          <p className="mt-2 text-sm theme-text-secondary">
            Total:{" "}
            <span className="font-semibold theme-text-primary">
              {formatCurrency(product.priceCents * quantity)}
            </span>
          </p>
        </div>

        {/* Actions */}
        <div className="flex gap-3">
          <button
            onClick={onClose}
            className="flex-1 rounded-full border border-white/20 bg-white/5 px-4 py-3 text-sm font-semibold theme-text-primary transition hover:bg-white/10"
          >
            Cancel
          </button>
          <button
            onClick={handleConfirm}
            disabled={!canAdd || isOutOfStock}
            className="flex-1 rounded-full bg-gradient-to-r from-sky-400 via-blue-500 to-indigo-500 px-4 py-3 text-sm font-semibold text-white shadow-lg transition hover:shadow-xl disabled:cursor-not-allowed disabled:opacity-50"
          >
            Add to Cart
          </button>
        </div>

        <p className="mt-4 text-center text-xs theme-text-secondary">
          Press{" "}
          <kbd className="rounded border border-white/20 bg-white/5 px-2 py-1">
            Enter
          </kbd>{" "}
          to confirm,{" "}
          <kbd className="rounded border border-white/20 bg-white/5 px-2 py-1">
            Esc
          </kbd>{" "}
          to cancel
        </p>
      </div>
    </div>
  );
}

import { useState, useEffect, useRef, useCallback } from "react";
import { useScannerDeviceStore } from "../stores/scannerDeviceStore";
import {
  registerUSBDevice,
  registerBluetoothDevice,
  sendDeviceHeartbeat,
} from "../services/scannerDeviceService";
import { useAuthStore } from "../stores/authStore";
import toast from "react-hot-toast";
import { CameraScanner } from "./CameraScanner";

interface ScannerInputProps {
  onScan: (barcode: string) => void;
  placeholder?: string;
  autoFocus?: boolean;
  className?: string;
}

export function ScannerInput({
  onScan,
  placeholder = "Scan barcode/QR with scanner, or type and press Enter...",
  autoFocus = true,
  className = "",
}: ScannerInputProps) {
  const [input, setInput] = useState("");
  const [showCameraScanner, setShowCameraScanner] = useState(false);
  const inputRef = useRef<HTMLInputElement>(null);
  const scanTimeoutRef = useRef<NodeJS.Timeout | null>(null);
  const lastScanTimeRef = useRef<number>(0);
  const usbDeviceRegisteredRef = useRef(false);
  const bluetoothDeviceRef = useRef<any | null>(null);

  const { addDevice, markDeviceUsed, setActiveDevice, getActiveDevice } =
    useScannerDeviceStore();
  const { user } = useAuthStore();
  const activeDevice = getActiveDevice();

  // Handle rapid keyboard input from USB/Bluetooth scanners
  useEffect(() => {
    const inputEl = inputRef.current;
    if (!inputEl) return;

    const handleInput = (e: Event) => {
      const target = e.target as HTMLInputElement;
      const value = target.value;

      // Clear any existing timeout
      if (scanTimeoutRef.current) {
        clearTimeout(scanTimeoutRef.current);
      }

      // Detect rapid input (likely from scanner)
      const now = Date.now();
      lastScanTimeRef.current = now;

      // If input is coming very fast (< 100ms between chars), it's likely a scanner
      // Wait a bit longer for the scan to complete, then process
      scanTimeoutRef.current = setTimeout(() => {
        if (value.trim() && value.length >= 4) {
          // Minimum barcode length is typically 4+ characters

          // Register USB device on first scan if not already registered
          if (!usbDeviceRegisteredRef.current) {
            registerUSBScanner();
          }

          // Mark device as used
          const activeDevice = useScannerDeviceStore
            .getState()
            .getActiveDevice();
          if (activeDevice) {
            markDeviceUsed(activeDevice.id);
            sendDeviceHeartbeat(activeDevice.id, user?.id).catch((err) =>
              console.warn("Failed to send heartbeat", err),
            );
          }

          onScan(value.trim());
          setInput("");
          // Only refocus if this input was the one that had focus
          if (document.activeElement === inputEl) {
            inputEl.focus();
          }
        }
      }, 150); // Wait 150ms after last character for scanner completion
    };

    inputEl.addEventListener("input", handleInput);
    return () => {
      inputEl.removeEventListener("input", handleInput);
      if (scanTimeoutRef.current) {
        clearTimeout(scanTimeoutRef.current);
      }
    };
  }, [onScan, markDeviceUsed, user?.id]);

  // Register USB scanner on first scan
  // Most USB scanners work as HID keyboards and don't need explicit registration
  // They automatically type into input fields when scanning
  const registerUSBScanner = useCallback(async () => {
    if (usbDeviceRegisteredRef.current) return;

    try {
      // Try to register without requesting Web USB access first
      // Most scanners work as keyboards and don't need Web USB API
      const registeredDevice = await registerUSBDevice(
        user?.locationId,
        user?.id,
        undefined,
      );
      const deviceId = addDevice(registeredDevice);
      setActiveDevice(deviceId);
      usbDeviceRegisteredRef.current = true;
      console.log("USB scanner registered:", registeredDevice.name);
      await sendDeviceHeartbeat(deviceId, user?.id);
    } catch (error) {
      // Registration failure is okay - scanner will still work as keyboard
      console.log("USB scanner registration note:", error);
    }
  }, [user?.locationId, user?.id, addDevice, setActiveDevice]);

  // Auto-focus for keyboard scanners (only if explicitly enabled)
  useEffect(() => {
    if (!autoFocus) return;

    const inputEl = inputRef.current;
    if (!inputEl) return;

    // Only auto-focus on mount if no other input is focused
    const activeElement = document.activeElement;
    const isInputFocused =
      activeElement &&
      (activeElement.tagName === "INPUT" ||
        activeElement.tagName === "TEXTAREA" ||
        activeElement.getAttribute("contenteditable") === "true");

    if (!isInputFocused) {
      // Small delay to avoid interfering with page load
      const timer = setTimeout(() => {
        inputEl.focus();
      }, 100);
      return () => clearTimeout(timer);
    }

    // Don't add blur handler - let users click other inputs freely
  }, [autoFocus]);

  // Bluetooth scanner support
  const connectBluetoothScanner = useCallback(async () => {
    try {
      if (!(navigator as any).bluetooth) {
        throw new Error(
          "Web Bluetooth API not supported. Use Chrome/Edge on desktop or Android.",
        );
      }

      const isSecure =
        window.location.protocol === "https:" ||
        window.location.hostname === "localhost" ||
        window.location.hostname === "127.0.0.1";

      if (!isSecure) {
        throw new Error("Bluetooth requires HTTPS or localhost.");
      }

      toast.loading("Searching for Bluetooth scanners...", {
        id: "bluetooth-connect",
      });

      const device = await (navigator as any).bluetooth.requestDevice({
        filters: [
          { services: ["00001812-0000-1000-8000-00805f9b34fb"] },
          { namePrefix: "Scanner" },
          { namePrefix: "Barcode" },
          { namePrefix: "QR" },
        ],
        optionalServices: [
          "battery_service",
          "device_information",
          "00001812-0000-1000-8000-00805f9b34fb",
        ],
      });

      toast.dismiss("bluetooth-connect");
      toast.loading("Connecting to device...", { id: "bluetooth-connect" });

      if (device.gatt) {
        try {
          const server = await device.gatt.connect();
          console.log("GATT server connected:", server);
        } catch (gattError) {
          console.warn(
            "GATT connection failed (device may be HID-only):",
            gattError,
          );
        }
      }

      const deviceData = await registerBluetoothDevice(
        device,
        user?.locationId,
        user?.id,
      );
      const deviceId = addDevice({
        ...deviceData,
        isActive: true,
      });
      setActiveDevice(deviceId);
      bluetoothDeviceRef.current = device;
      await sendDeviceHeartbeat(deviceId, user?.id);

      device.addEventListener("gattserverdisconnected", () => {
        console.log("Bluetooth scanner disconnected");
        toast.error(`Bluetooth scanner "${device.name}" disconnected`);
        if (deviceId) {
          useScannerDeviceStore
            .getState()
            .updateDevice(deviceId, { isActive: false });
          sendDeviceHeartbeat(deviceId, user?.id, { isActive: false }).catch(
            (err) => console.warn("Failed to send heartbeat", err),
          );
        }
        bluetoothDeviceRef.current = null;
      });

      toast.dismiss("bluetooth-connect");
      toast.success(`Bluetooth scanner "${device.name}" connected!`);
    } catch (error: any) {
      toast.dismiss("bluetooth-connect");

      if (error.name === "NotFoundError") {
        toast.error("No Bluetooth scanner found nearby.");
      } else if (error.name === "SecurityError") {
        toast.error("Bluetooth access denied.");
      } else if (error.name !== "AbortError") {
        toast.error(error.message || "Failed to connect Bluetooth scanner");
      }
    }
  }, [user?.locationId, user?.id, addDevice, setActiveDevice]);

  const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    // If Enter is pressed and input has value, treat as barcode scan
    if (e.key === "Enter" && input.trim()) {
      e.preventDefault();
      onScan(input.trim());
      setInput("");
      // Only refocus if autoFocus is enabled and this input was the one that had focus
      if (autoFocus && document.activeElement === inputRef.current) {
        setTimeout(() => {
          inputRef.current?.focus();
        }, 50);
      }
    }
  };

  const isBluetoothSupported =
    typeof navigator !== "undefined" && "bluetooth" in (navigator as any);
  const isCameraSupported =
    typeof navigator !== "undefined" &&
    "mediaDevices" in navigator &&
    "getUserMedia" in navigator.mediaDevices;

  const handleCameraScan = (barcode: string) => {
    onScan(barcode);
    // Keep camera open for multiple scans
  };

  return (
    <>
      <div className={`space-y-3 ${className}`}>
        <div className="theme-surface flex flex-col sm:flex-row items-stretch sm:items-center gap-2 sm:gap-3 rounded-2xl border border-white/10 bg-slate-950/40 p-3 sm:p-4 shadow-inner shadow-black/40">
          <div className="flex items-center gap-2 sm:gap-3 flex-1 min-w-0">
            <span className="theme-text-secondary text-lg flex-shrink-0">
              📷
            </span>
            <input
              ref={inputRef}
              type="text"
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={handleKeyDown}
              placeholder={placeholder}
              className="flex-1 min-w-0 bg-transparent text-base sm:text-lg theme-text-primary placeholder:text-current/50 focus:outline-none font-mono"
              autoFocus={autoFocus}
              autoComplete="off"
            />
          </div>
          <div className="flex gap-2 sm:gap-3 flex-shrink-0">
            {isCameraSupported && (
              <button
                onClick={() => setShowCameraScanner(true)}
                className="theme-chip rounded-full border border-emerald-400/40 bg-emerald-500/15 px-4 sm:px-3 py-2.5 sm:py-2 text-sm font-semibold text-emerald-200 transition hover:bg-emerald-500/25 active:scale-95 touch-manipulation flex-1 sm:flex-initial items-center justify-center gap-1.5 sm:gap-0"
                title="Open camera scanner"
              >
                <span className="text-base sm:text-lg">📷</span>
                <span className="sm:hidden">Camera</span>
                <span className="hidden sm:inline">Camera</span>
              </button>
            )}
            {isBluetoothSupported && (
              <button
                onClick={connectBluetoothScanner}
                className="theme-chip rounded-full border border-purple-400/40 bg-purple-500/15 px-4 sm:px-3 py-2.5 sm:py-2 text-sm font-semibold text-purple-200 transition hover:bg-purple-500/25 active:scale-95 touch-manipulation flex-1 sm:flex-initial items-center justify-center gap-1.5 sm:gap-0"
                title="Connect Bluetooth scanner"
              >
                <span className="text-base sm:text-lg">📡</span>
                <span className="sm:hidden">BT</span>
                <span className="hidden sm:inline">Bluetooth</span>
              </button>
            )}
          </div>
        </div>
        {activeDevice && (
          <p className="text-xs theme-text-secondary text-center">
            Active scanner:{" "}
            <span className="font-semibold text-sky-400">
              {activeDevice.name}
            </span>
          </p>
        )}
        {!activeDevice && (
          <p className="text-xs theme-text-secondary text-center">
            💡 <strong className="theme-text-primary">Tip:</strong> USB scanners
            work automatically - just plug in and scan!
          </p>
        )}
        {input && (
          <p className="text-xs theme-text-secondary text-center">
            Press <kbd className="px-2 py-1 bg-white/10 rounded">Enter</kbd> or
            wait for auto-scan
          </p>
        )}
      </div>
      {showCameraScanner && (
        <CameraScanner
          isOpen={showCameraScanner}
          onScan={handleCameraScan}
          onClose={() => setShowCameraScanner(false)}
        />
      )}
    </>
  );
}

import { useState, useEffect } from "react";
import axios from "axios";
import toast from "react-hot-toast";
import { API_URL } from "../config";
import {
  formatCurrency,
  formatNumber,
  parseFormattedNumber,
  handleNumberInputChange,
} from "../utils/numberFormat";

interface Payment {
  id: string;
  method: "cash" | "card" | "qr";
  amountCents: number;
  status: string;
}

interface SplitPaymentModalProps {
  isOpen: boolean;
  orderId: string | null;
  totalCents: number;
  accessToken: string | null;
  onClose: () => void;
  onComplete: () => void;
}

export function SplitPaymentModal({
  isOpen,
  orderId,
  totalCents,
  accessToken,
  onClose,
  onComplete,
}: SplitPaymentModalProps) {
  const [payments, setPayments] = useState<Payment[]>([]);
  const [selectedMethod, setSelectedMethod] = useState<
    "cash" | "card" | "qr" | null
  >(null);
  const [cashAmount, setCashAmount] = useState("");
  const [paymentAmount, setPaymentAmount] = useState("");
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    if (isOpen && orderId && accessToken) {
      loadPayments();
    }
  }, [isOpen, orderId, accessToken]);

  const loadPayments = async () => {
    if (!orderId || !accessToken) return;
    try {
      const response = await axios.get(
        `${API_URL}/api/v1/orders/${orderId}/payments`,
        {
          headers: { Authorization: `Bearer ${accessToken}` },
        },
      );
      setPayments(response.data || []);
    } catch (error) {
      console.error("Failed to load payments:", error);
    }
  };

  const getTotalPaid = () => {
    return payments
      .filter((p) => p.status === "completed")
      .reduce((sum, p) => sum + p.amountCents, 0);
  };

  const getRemaining = () => {
    return totalCents - getTotalPaid();
  };

  const handleAddPayment = async () => {
    if (!orderId || !accessToken || !selectedMethod) return;

    const amount =
      selectedMethod === "cash"
        ? parseFormattedNumber(cashAmount) * 100
        : parseFormattedNumber(paymentAmount) * 100;

    if (isNaN(amount) || amount <= 0) {
      toast.error("Please enter a valid amount");
      return;
    }

    const remaining = getRemaining();
    if (amount > remaining) {
      toast.error(
        `Amount exceeds remaining balance of ${formatCurrency(remaining)}`,
      );
      return;
    }

    setLoading(true);
    try {
      await axios.post(
        `${API_URL}/api/v1/orders/${orderId}/payments/initiate`,
        {
          method: selectedMethod,
          amount: Math.round(amount),
        },
        { headers: { Authorization: `Bearer ${accessToken}` } },
      );

      toast.success("Payment added");
      setSelectedMethod(null);
      setCashAmount("");
      setPaymentAmount("");
      await loadPayments();

      // Check if fully paid
      const newRemaining = getRemaining() - amount;
      if (newRemaining <= 0) {
        toast.success("Order fully paid!");
        setTimeout(() => {
          onComplete();
        }, 1000);
      }
    } catch (error: any) {
      toast.error(error.response?.data?.message || "Failed to add payment");
    } finally {
      setLoading(false);
    }
  };

  if (!isOpen || !orderId) return null;

  const totalPaid = getTotalPaid();
  const remaining = getRemaining();
  const isFullyPaid = remaining <= 0;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm p-4">
      <div className="theme-card w-full max-w-2xl rounded-3xl border p-8 shadow-2xl">
        <div className="mb-6">
          <h2 className="theme-text-primary text-2xl font-bold mb-2">
            Split Payment
          </h2>
          <p className="theme-text-secondary text-sm">
            Add multiple payment methods for this order
          </p>
        </div>

        {/* Payment Summary */}
        <div className="mb-6 space-y-3">
          <div className="theme-surface rounded-2xl border p-4">
            <div className="flex justify-between text-sm theme-text-secondary mb-2">
              <span>Total Amount</span>
              <span className="theme-text-primary font-semibold">
                {formatCurrency(totalCents)}
              </span>
            </div>
            <div className="flex justify-between text-sm theme-text-secondary mb-2">
              <span>Total Paid</span>
              <span className="font-semibold text-emerald-400">
                {formatCurrency(totalPaid)}
              </span>
            </div>
            <div className="theme-divider my-3 h-px" />
            <div className="flex items-center justify-between">
              <span className="theme-text-primary text-lg font-semibold">
                Remaining
              </span>
              <span
                className={`text-2xl font-bold ${isFullyPaid ? "text-emerald-400" : "text-amber-400"}`}
              >
                {formatCurrency(remaining)}
              </span>
            </div>
          </div>

          {/* Existing Payments */}
          {payments.length > 0 && (
            <div className="theme-surface rounded-2xl border p-4">
              <h3 className="theme-text-primary font-semibold mb-3">
                Payments Made
              </h3>
              <div className="space-y-2">
                {payments.map((payment) => (
                  <div
                    key={payment.id}
                    className="flex items-center justify-between rounded-lg bg-white/5 p-2 text-sm"
                  >
                    <div className="flex items-center gap-2">
                      <span>
                        {payment.method === "cash"
                          ? "💵"
                          : payment.method === "card"
                            ? "💳"
                            : "📱"}
                      </span>
                      <span className="theme-text-primary capitalize">
                        {payment.method}
                      </span>
                      <span
                        className={`text-xs ${
                          payment.status === "completed"
                            ? "text-emerald-400"
                            : "text-amber-400"
                        }`}
                      >
                        {payment.status}
                      </span>
                    </div>
                    <span className="theme-text-primary font-semibold">
                      {formatCurrency(payment.amountCents)}
                    </span>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* Add Payment */}
          {!isFullyPaid && (
            <div className="theme-surface rounded-2xl border p-4">
              <h3 className="theme-text-primary font-semibold mb-3">
                Add Payment
              </h3>

              {!selectedMethod ? (
                <div className="grid grid-cols-3 gap-3">
                  <button
                    onClick={() => setSelectedMethod("cash")}
                    className="rounded-xl border border-white/20 bg-transparent p-4 text-center transition hover:bg-white/5"
                  >
                    <div className="text-3xl mb-2">💵</div>
                    <div className="text-sm font-semibold theme-text-primary">
                      Cash
                    </div>
                  </button>
                  <button
                    onClick={() => setSelectedMethod("card")}
                    className="rounded-xl border border-white/20 bg-transparent p-4 text-center transition hover:bg-white/5"
                  >
                    <div className="text-3xl mb-2">💳</div>
                    <div className="text-sm font-semibold theme-text-primary">
                      Card
                    </div>
                  </button>
                  <button
                    onClick={() => setSelectedMethod("qr")}
                    className="rounded-xl border border-white/20 bg-transparent p-4 text-center transition hover:bg-white/5"
                  >
                    <div className="text-3xl mb-2">📱</div>
                    <div className="text-sm font-semibold theme-text-primary">
                      QR
                    </div>
                  </button>
                </div>
              ) : (
                <div className="space-y-4">
                  <div>
                    <label className="block text-sm font-medium theme-text-secondary mb-2">
                      Amount (
                      {selectedMethod === "cash"
                        ? "Cash Received"
                        : "Payment Amount"}
                      )
                    </label>
                    <input
                      type="text"
                      value={
                        selectedMethod === "cash" ? cashAmount : paymentAmount
                      }
                      onChange={(e) => {
                        const { displayValue } = handleNumberInputChange(
                          e.target.value,
                          true,
                        );
                        if (selectedMethod === "cash") {
                          setCashAmount(displayValue);
                        } else {
                          setPaymentAmount(displayValue);
                        }
                      }}
                      placeholder="0.00"
                      className="w-full theme-surface rounded-lg border border-white/20 bg-transparent px-4 py-3 text-xl font-semibold theme-text-primary focus:border-sky-400 focus:outline-none"
                      autoFocus
                    />
                    <p className="mt-1 text-xs theme-text-secondary">
                      Max: {formatCurrency(remaining)}
                    </p>
                  </div>
                  <div className="flex gap-3">
                    <button
                      onClick={() => {
                        setSelectedMethod(null);
                        setCashAmount("");
                        setPaymentAmount("");
                      }}
                      className="flex-1 rounded-full border border-white/20 bg-transparent px-4 py-2 text-sm font-semibold theme-text-primary transition hover:bg-white/5"
                    >
                      Cancel
                    </button>
                    <button
                      onClick={handleAddPayment}
                      disabled={
                        loading ||
                        (selectedMethod === "cash"
                          ? !cashAmount
                          : !paymentAmount)
                      }
                      className="flex-1 rounded-full bg-gradient-to-r from-sky-400 via-sky-500 to-sky-400 px-4 py-2 text-sm font-semibold text-sky-950 shadow-lg transition hover:shadow-sky-900/70 disabled:cursor-not-allowed disabled:opacity-50"
                    >
                      {loading ? "Processing..." : "Add Payment"}
                    </button>
                  </div>
                </div>
              )}
            </div>
          )}

          {isFullyPaid && (
            <div className="rounded-xl border border-emerald-400/40 bg-emerald-500/15 p-4 text-center">
              <p className="text-lg font-semibold text-emerald-200">
                ✅ Order Fully Paid!
              </p>
            </div>
          )}
        </div>

        <div className="flex gap-3">
          <button
            onClick={onClose}
            className="flex-1 rounded-full border border-white/20 bg-transparent px-6 py-3 font-semibold theme-text-primary transition hover:bg-white/5"
          >
            {isFullyPaid ? "Close" : "Cancel"}
          </button>
        </div>
      </div>
    </div>
  );
}

import { useState, useEffect, useRef } from "react";
import { useAuthStore } from "../stores/authStore";
import axios from "axios";
import toast from "react-hot-toast";
import { Link } from "react-router-dom";
import { API_URL } from "../config";
import { BrandMark } from "../components/BrandMark";
import { ThemeToggle } from "../components/ThemeToggle";
import { ScannerInput } from "../components/ScannerInput";
import { AlertBanner } from "../components/AlertBanner";
import { format } from "date-fns";
import {
  formatNumber,
  formatCurrency,
  parseFormattedNumber,
  handleNumberInputChange,
} from "../utils/numberFormat";
import { lookupBarcode } from "../services/barcodeLookupService";

interface InventoryItem {
  id: string;
  productId: string;
  product: {
    id: string;
    name: string;
    sku: string;
    barcode?: string;
    priceCents?: number;
  };
  quantity: number;
  reorderPoint?: number;
  costCents?: number;
  salesPriceCents?: number;
  createdAt: string;
  updatedAt: string;
  lastTransaction?: {
    timestamp: string;
    userId?: string;
    user?: {
      id: string;
      name: string;
    };
    type: string;
  };
}

type InventoryFormState = {
  name: string;
  description: string;
  quantity: string;
  costCents: string;
  priceCents: string;
  barcode: string;
  categoryId: string;
  categoryName: string;
  brandId: string;
  brandName: string;
  batchNumber: string;
  expiryDate: string;
};

const createEmptyInventoryForm = (): InventoryFormState => ({
  name: "",
  description: "",
  quantity: "",
  costCents: "",
  priceCents: "",
  barcode: "",
  categoryId: "",
  categoryName: "",
  brandId: "",
  brandName: "",
  batchNumber: "",
  expiryDate: "",
});

export function AddInventoryPage() {
  const { user, logout, accessToken, tenant } = useAuthStore();
  const [inventory, setInventory] = useState<InventoryItem[]>([]);
  const [loading, setLoading] = useState(false);
  const [effectiveLocationId, setEffectiveLocationId] = useState<string | null>(
    user?.locationId || null,
  );

  // Inventory form state
  const industry = tenant?.industry as string | undefined;
  const industryDefaults =
    industry === "PHARMACEUTICAL" || industry === "GROCERY"
      ? { expiryTracking: true, batchTracking: true }
      : {};
  const featureFlags = tenant?.feature_flags || industryDefaults;
  const expiryTrackingEnabled = featureFlags?.expiryTracking === true;
  const batchTrackingEnabled = featureFlags?.batchTracking === true;

  const [inventoryForm, setInventoryForm] = useState<InventoryFormState>(
    createEmptyInventoryForm(),
  );
  const [categoryMode, setCategoryMode] = useState<"existing" | "new">(
    "existing",
  );
  const [brandMode, setBrandMode] = useState<"existing" | "new">("existing");
  const savedCategoryId = useRef<string>("");
  const savedBrandId = useRef<string>("");

  const [categories, setCategories] = useState<
    Array<{ id: string; name: string }>
  >([]);
  const [brands, setBrands] = useState<Array<{ id: string; name: string }>>([]);
  const [editingQuantities, setEditingQuantities] = useState<
    Record<string, string>
  >({});
  const [updatingQuantities, setUpdatingQuantities] = useState<
    Record<string, boolean>
  >({});
  const [editingItem, setEditingItem] = useState<{
    productId: string;
    quantity: string;
    reorderPoint: string;
    costCents: string;
    salesPriceCents: string;
  } | null>(null);

  // Get the effective locationId (user's locationId or first location for tenant)
  const getEffectiveLocationId = async (): Promise<string | null> => {
    if (!accessToken || !user) return null;

    if (user.locationId) {
      return user.locationId;
    }

    try {
      const response = await axios.get(`${API_URL}/api/v1/locations`, {
        headers: { Authorization: `Bearer ${accessToken}` },
      });
      const locations = response.data || [];
      if (locations.length > 0) {
        return locations[0].id;
      }
    } catch (error) {
      console.error("Failed to fetch locations:", error);
    }

    return null;
  };

  const loadInventory = async () => {
    if (!accessToken || !user) return;

    setLoading(true);
    try {
      const locationId = await getEffectiveLocationId();
      if (!locationId) {
        setInventory([]);
        return;
      }

      setEffectiveLocationId(locationId);

      const response = await axios.get(
        `${API_URL}/api/v1/inventory/${locationId}/stock`,
        { headers: { Authorization: `Bearer ${accessToken}` } },
      );
      setInventory(response.data || []);
    } catch (error: any) {
      console.error("Failed to load inventory:", error);
      if (error.response?.status === 401) {
        toast.error("Authentication expired. Please log in again.");
      } else {
        toast.error(
          error.response?.data?.message || "Failed to load inventory",
        );
      }
    } finally {
      setLoading(false);
    }
  };

  const loadCategories = async () => {
    if (!accessToken) return;
    try {
      const response = await axios.get(`${API_URL}/api/v1/categories`, {
        headers: { Authorization: `Bearer ${accessToken}` },
      });
      setCategories(response.data || []);
    } catch (error) {
      console.error("Failed to load categories:", error);
    }
  };

  const loadBrands = async () => {
    if (!accessToken) return;
    try {
      const response = await axios.get(`${API_URL}/api/v1/brands`, {
        headers: { Authorization: `Bearer ${accessToken}` },
      });
      setBrands(response.data || []);
    } catch (error) {
      console.error("Failed to load brands:", error);
    }
  };

  // Handle barcode scan - search for existing product and auto-fill form
  const handleBarcodeScan = async (barcode: string) => {
    // Trim and normalize barcode
    const trimmedBarcode = barcode.trim();

    if (!trimmedBarcode || !accessToken) {
      // If no barcode, just set it in the form (empty string)
      setInventoryForm({ ...inventoryForm, barcode: trimmedBarcode });
      return;
    }

    // First, set the trimmed barcode in the form (this ensures it's saved)
    setInventoryForm({ ...inventoryForm, barcode: trimmedBarcode });

    try {
      // Search for existing product by barcode
      const response = await axios.get(
        `${API_URL}/api/v1/products?query=${encodeURIComponent(barcode)}`,
        { headers: { Authorization: `Bearer ${accessToken}` } },
      );

      const products = response.data || [];
      // Try to find exact barcode match first
      const product =
        products.find((p: any) => p.barcode === barcode) || products[0];

      if (product) {
        // Auto-fill form with product details
        toast.success(`Found product: ${product.name}`);

        // Get inventory details if available
        const locationId = await getEffectiveLocationId();
        if (locationId) {
          try {
            const invResponse = await axios.get(
              `${API_URL}/api/v1/inventory/${locationId}/stock`,
              { headers: { Authorization: `Bearer ${accessToken}` } },
            );
            const invItem = invResponse.data.find(
              (inv: any) => inv.productId === product.id,
            );

            if (invItem) {
              // Product exists in inventory - fill with existing data
              setInventoryForm({
                ...createEmptyInventoryForm(),
                name: product.name,
                description: product.description || "",
                quantity: formatNumber(invItem.quantity),
                costCents: invItem.costCents
                  ? formatNumber(invItem.costCents / 100)
                  : "",
                priceCents: invItem.salesPriceCents
                  ? formatNumber(invItem.salesPriceCents / 100)
                  : product.priceCents
                    ? formatNumber(product.priceCents / 100)
                    : "",
                barcode: product.barcode || barcode,
                categoryId: product.categoryId || "",
                categoryName: product.category?.name || "",
                brandId: product.brandId || "",
                brandName: product.brand?.name || "",
              });

              // Set category/brand mode and IDs based on what's available
              if (product.categoryId) {
                setCategoryMode("existing");
                savedCategoryId.current = product.categoryId;
                setInventoryForm((prev) => ({
                  ...prev,
                  categoryId: product.categoryId,
                }));
              }
              if (product.brandId) {
                setBrandMode("existing");
                savedBrandId.current = product.brandId;
                setInventoryForm((prev) => ({
                  ...prev,
                  brandId: product.brandId,
                }));
              }

              toast(
                "Form filled with existing inventory data. Update quantities/prices as needed.",
                { icon: "ℹ️" },
              );
            } else {
              // Product exists but not in inventory - fill with product data only
              setInventoryForm({
                ...createEmptyInventoryForm(),
                name: product.name,
                description: product.description || "",
                quantity: "",
                costCents: "",
                priceCents: product.priceCents
                  ? formatNumber(product.priceCents / 100)
                  : "",
                barcode: product.barcode || barcode,
                categoryId: product.categoryId || "",
                categoryName: product.category?.name || "",
                brandId: product.brandId || "",
                brandName: product.brand?.name || "",
              });

              if (product.categoryId) {
                setCategoryMode("existing");
                savedCategoryId.current = product.categoryId;
                setInventoryForm((prev) => ({
                  ...prev,
                  categoryId: product.categoryId,
                }));
              }
              if (product.brandId) {
                setBrandMode("existing");
                savedBrandId.current = product.brandId;
                setInventoryForm((prev) => ({
                  ...prev,
                  brandId: product.brandId,
                }));
              }

              toast("Product found! Please enter quantity and cost price.", {
                icon: "ℹ️",
              });
            }
          } catch (invError) {
            // If inventory check fails, just fill with product data
            setInventoryForm({
              ...createEmptyInventoryForm(),
              name: product.name,
              description: product.description || "",
              quantity: "",
              costCents: "",
              priceCents: product.priceCents
                ? formatNumber(product.priceCents / 100)
                : "",
              barcode: product.barcode || barcode,
              categoryId: product.categoryId || "",
              categoryName: product.category?.name || "",
              brandId: product.brandId || "",
              brandName: product.brand?.name || "",
            });

            if (product.categoryId) {
              setCategoryMode("existing");
              savedCategoryId.current = product.categoryId;
              setInventoryForm((prev) => ({
                ...prev,
                categoryId: product.categoryId,
              }));
            }
            if (product.brandId) {
              setBrandMode("existing");
              savedBrandId.current = product.brandId;
              setInventoryForm((prev) => ({
                ...prev,
                brandId: product.brandId,
              }));
            }
          }
        } else {
          // No location - just fill with product data
          setInventoryForm({
            ...createEmptyInventoryForm(),
            name: product.name,
            description: product.description || "",
            quantity: "",
            costCents: "",
            priceCents: product.priceCents
              ? formatNumber(product.priceCents / 100)
              : "",
            barcode: product.barcode || barcode,
            categoryId: product.categoryId || "",
            categoryName: "",
            brandId: product.brandId || "",
            brandName: "",
          });

          if (product.categoryId) {
            setCategoryMode("existing");
            savedCategoryId.current = product.categoryId;
          }
          if (product.brandId) {
            setBrandMode("existing");
            savedBrandId.current = product.brandId;
          }
        }
      } else {
        // Product not found locally - try external barcode lookup
        toast("Product not found locally. Searching external databases...", {
          icon: "🔍",
        });

        try {
          const externalProduct = await lookupBarcode(barcode);

          if (externalProduct) {
            // Found product in external database - auto-fill form
            toast.success(
              `Found product: ${externalProduct.name} (from ${externalProduct.source})`,
            );

            // Try to find or create category
            let categoryId = "";
            let categoryName = "";
            if (externalProduct.category) {
              // Try to find existing category
              const categoryMatch = categories.find(
                (cat) =>
                  cat.name.toLowerCase() ===
                  externalProduct.category!.toLowerCase(),
              );
              if (categoryMatch) {
                categoryId = categoryMatch.id;
                setCategoryMode("existing");
                savedCategoryId.current = categoryMatch.id;
              } else {
                categoryName = externalProduct.category;
                setCategoryMode("new");
              }
            }

            // Try to find or create brand
            let brandId = "";
            let brandName = "";
            if (externalProduct.brand) {
              // Try to find existing brand
              const brandMatch = brands.find(
                (brand) =>
                  brand.name.toLowerCase() ===
                  externalProduct.brand!.toLowerCase(),
              );
              if (brandMatch) {
                brandId = brandMatch.id;
                setBrandMode("existing");
                savedBrandId.current = brandMatch.id;
              } else {
                brandName = externalProduct.brand;
                setBrandMode("new");
              }
            }

            // Auto-fill form with external product data
            setInventoryForm({
              ...createEmptyInventoryForm(),
              name: externalProduct.name,
              description: externalProduct.description || "",
              quantity: "",
              costCents: "",
              priceCents: externalProduct.price
                ? formatNumber(externalProduct.price)
                : "",
              barcode: barcode,
              categoryId: categoryId,
              categoryName: categoryName,
              brandId: brandId,
              brandName: brandName,
            });

            toast(
              "Product information loaded from external database. Please review and add quantity/cost.",
              {
                icon: "✅",
                duration: 5000,
              },
            );
          } else {
            // Not found in external databases either
            toast(
              "Product not found in external databases. You can create a new product manually.",
              {
                icon: "ℹ️",
                duration: 5000,
              },
            );
          }
        } catch (lookupError) {
          console.error("External barcode lookup failed:", lookupError);
          toast(
            "Could not fetch product info from external databases. You can still create a new product manually.",
            {
              icon: "⚠️",
            },
          );
        }
      }
    } catch (error: any) {
      console.error("Barcode scan failed:", error);
      // If search fails, try external lookup as fallback
      try {
        const externalProduct = await lookupBarcode(barcode);
        if (externalProduct) {
          toast.success(`Found product externally: ${externalProduct.name}`);
          setInventoryForm({
            ...inventoryForm,
            name: externalProduct.name,
            description: externalProduct.description || "",
            barcode: barcode,
          });
        } else {
          toast.error(
            "Failed to search product by barcode. You can still create a new product.",
          );
        }
      } catch (lookupError) {
        toast.error(
          "Failed to search product by barcode. You can still create a new product.",
        );
      }
    }
  };

  const handleQuantityInputChange = (itemId: string, value: string) => {
    setEditingQuantities((prev) => ({
      ...prev,
      [itemId]: value,
    }));
  };

  const toggleCategoryMode = () => {
    setCategoryMode((prevMode) => {
      const nextMode = prevMode === "existing" ? "new" : "existing";
      setInventoryForm((form) => {
        if (nextMode === "new") {
          savedCategoryId.current = form.categoryId;
          return { ...form, categoryId: "" };
        }
        return { ...form, categoryId: savedCategoryId.current || "" };
      });
      return nextMode;
    });
  };

  const toggleBrandMode = () => {
    setBrandMode((prevMode) => {
      const nextMode = prevMode === "existing" ? "new" : "existing";
      setInventoryForm((form) => {
        if (nextMode === "new") {
          savedBrandId.current = form.brandId;
          return { ...form, brandId: "" };
        }
        return { ...form, brandId: savedBrandId.current || "" };
      });
      return nextMode;
    });
  };

  const handleUpdateQuantity = async (item: InventoryItem) => {
    if (!user || !accessToken) {
      toast.error("Please log in before adjusting inventory.");
      return;
    }

    const rawValue = editingQuantities[item.id] ?? item.quantity.toString();
    const newQuantity = parseInt(rawValue, 10);
    if (isNaN(newQuantity) || newQuantity < 0) {
      toast.error("Quantity must be a non-negative number.");
      return;
    }

    if (newQuantity === item.quantity) {
      toast("Quantity already up to date.");
      return;
    }

    const delta = newQuantity - item.quantity;
    const type = delta > 0 ? "received" : "adjust";

    setUpdatingQuantities((prev) => ({
      ...prev,
      [item.id]: true,
    }));

    try {
      // Backend will automatically resolve locationId and userId from JWT/user context
      await axios.post(
        `${API_URL}/api/v1/inventory/adjust`,
        {
          productId: item.product.id,
          delta,
          type,
          // Do NOT send userId or locationId – backend resolves them to avoid validation errors
          notes: "Updated via inventory management",
        },
        {
          headers: {
            Authorization: `Bearer ${accessToken}`,
            "Content-Type": "application/json",
          },
        },
      );

      toast.success(`Updated ${item.product.name} quantity to ${newQuantity}`);
      await loadInventory();
      setEditingQuantities((prev) => {
        const next = { ...prev };
        delete next[item.id];
        return next;
      });
    } catch (error: any) {
      console.error("Failed to update quantity:", error);

      // Extract full error message
      let errorMessage = "Failed to update inventory quantity";
      if (error.response?.data) {
        if (error.response.data.message) {
          errorMessage = error.response.data.message;
        } else if (error.response.data.error) {
          errorMessage = error.response.data.error;
        } else if (typeof error.response.data === "string") {
          errorMessage = error.response.data;
        } else if (Array.isArray(error.response.data.message)) {
          errorMessage = error.response.data.message.join(", ");
        }
      } else if (error.message) {
        errorMessage = error.message;
      }

      if (error.response?.status === 401) {
        errorMessage = "Authentication expired. Please log in again.";
      }

      toast.error(errorMessage);
    } finally {
      setUpdatingQuantities((prev) => {
        const next = { ...prev };
        delete next[item.id];
        return next;
      });
    }
  };

  const handleUpdateItem = async (productId: string) => {
    if (!editingItem || !accessToken) return;

    try {
      // Validate required fields
      if (!editingItem.costCents || !editingItem.salesPriceCents) {
        toast.error("Cost price and selling price are required");
        return;
      }

      const costCents = Math.round(
        parseFormattedNumber(editingItem.costCents) * 100,
      );
      const salesPriceCents = Math.round(
        parseFormattedNumber(editingItem.salesPriceCents) * 100,
      );

      if (
        isNaN(costCents) ||
        costCents < 0 ||
        isNaN(salesPriceCents) ||
        salesPriceCents < 0
      ) {
        toast.error("Invalid price values");
        return;
      }

      // Get current inventory to preserve values if not being updated
      const currentItem = inventory.find((inv) => inv.productId === productId);

      // Don't send locationId - let backend resolve it from user context
      // This avoids UUID validation errors
      await axios.put(
        `${API_URL}/api/v1/inventory/item`,
        {
          productId,
          // locationId will be resolved by backend from user context
          quantity: editingItem.quantity
            ? parseInt(
                parseFormattedNumber(editingItem.quantity).toString(),
                10,
              )
            : currentItem?.quantity || 0,
          reorderPoint: editingItem.reorderPoint
            ? parseInt(
                parseFormattedNumber(editingItem.reorderPoint).toString(),
                10,
              )
            : currentItem?.reorderPoint || undefined,
          costCents,
          salesPriceCents,
        },
        { headers: { Authorization: `Bearer ${accessToken}` } },
      );

      toast.success("Inventory item updated successfully");
      setEditingItem(null);
      loadInventory();
    } catch (error: any) {
      console.error("Update error:", error);
      const errorMessage =
        error.response?.data?.message ||
        error.message ||
        "Failed to update inventory item";
      toast.error(errorMessage);
    }
  };

  const handleSubmitInventory = async (e: React.FormEvent) => {
    e.preventDefault();

    if (
      !inventoryForm.name ||
      !inventoryForm.quantity ||
      !inventoryForm.costCents ||
      !inventoryForm.priceCents
    ) {
      toast.error(
        "Please fill in required fields: Name, Quantity, Cost Price, and Selling Price",
      );
      return;
    }

    const trimmedCategoryName = inventoryForm.categoryName.trim();
    const trimmedBrandName = inventoryForm.brandName.trim();

    if (categoryMode === "new" && !trimmedCategoryName) {
      toast.error(
        "Enter a name for the new category or switch to an existing one.",
      );
      return;
    }

    if (brandMode === "new" && !trimmedBrandName) {
      toast.error(
        "Enter a name for the new brand or switch to an existing one.",
      );
      return;
    }

    if (batchTrackingEnabled && !inventoryForm.batchNumber.trim()) {
      toast.error("Batch number is required for this tenant");
      return;
    }

    let expiryIso: string | undefined;
    if (inventoryForm.expiryDate) {
      const parsedExpiry = new Date(inventoryForm.expiryDate);
      if (Number.isNaN(parsedExpiry.getTime())) {
        toast.error("Invalid expiry date");
        return;
      }
      expiryIso = parsedExpiry.toISOString();
    }

    if (expiryTrackingEnabled && !expiryIso) {
      toast.error("Expiry date is required for this tenant");
      return;
    }

    if (!accessToken || !user) {
      toast.error("Not authenticated. Please log in again.");
      setTimeout(() => {
        window.location.href = "/login";
      }, 2000);
      return;
    }

    try {
      const quantity = parseInt(
        parseFormattedNumber(inventoryForm.quantity).toString(),
        10,
      );
      const costCents = Math.round(
        parseFormattedNumber(inventoryForm.costCents) * 100,
      );
      const priceCents = Math.round(
        parseFormattedNumber(inventoryForm.priceCents) * 100,
      );

      if (isNaN(quantity) || quantity < 0) {
        toast.error("Invalid quantity");
        return;
      }

      if (isNaN(costCents) || costCents < 0) {
        toast.error("Invalid cost price");
        return;
      }

      if (isNaN(priceCents) || priceCents < 0) {
        toast.error("Invalid selling price");
        return;
      }

      const response = await axios.post(
        `${API_URL}/api/v1/inventory/create-item`,
        {
          name: inventoryForm.name,
          description: inventoryForm.description || undefined,
          quantity,
          priceCents,
          costCents,
          barcode: inventoryForm.barcode || undefined,
          categoryId: inventoryForm.categoryId || undefined,
          categoryName: inventoryForm.categoryName || undefined,
          brandId: inventoryForm.brandId || undefined,
          brandName: inventoryForm.brandName || undefined,
          batchNumber: inventoryForm.batchNumber || undefined,
          expiryDate: expiryIso,
        },
        {
          headers: {
            Authorization: `Bearer ${accessToken}`,
            "Content-Type": "application/json",
          },
        },
      );

      if (response.status === 201 || response.status === 200) {
        toast.success(
          `Inventory added: ${inventoryForm.name} (${quantity} units)`,
        );

        // Reset form
        setInventoryForm(createEmptyInventoryForm());
        setCategoryMode("existing");
        setBrandMode("existing");
        savedCategoryId.current = "";
        savedBrandId.current = "";

        // Reload inventory
        await loadInventory();
      }
    } catch (error: any) {
      console.error("Failed to add inventory:", error);
      if (error.response?.status === 401) {
        toast.error("Authentication expired. Please log in again.");
      } else if (error.response?.status === 400) {
        const message = error.response?.data?.message || "Invalid request";
        toast.error(message);
      } else {
        toast.error(
          error.response?.data?.message ||
            error.message ||
            "Failed to add inventory",
        );
      }
    }
  };

  useEffect(() => {
    if (user && accessToken) {
