                          }}
                          className="w-full rounded-lg border border-white/10 bg-white/5 px-3 py-2 text-xs sm:text-sm theme-text-primary"
                          disabled={isLoadingTaxRules}
                        >
                          <option value="">Select VAT rule</option>
                          {taxRules.map((r) => (
                            <option key={r.id} value={r.id}>
                              {r.name}
                            </option>
                          ))}
                        </select>
                      </div>

                      <div>
                        <div className="theme-text-secondary text-[11px] sm:text-xs mb-1">
                          Override rate (%)
                        </div>
                        <input
                          value={
                            taxRateOverridePercent === null
                              ? ""
                              : String(taxRateOverridePercent)
                          }
                          onChange={(e) => {
                            const raw = e.target.value;
                            if (!raw.trim()) {
                              setTaxRateOverridePercent(null);
                              return;
                            }
                            const parsed = parseFloat(raw);
                            if (Number.isNaN(parsed) || parsed < 0) {
                              return;
                            }
                            setTaxRateOverridePercent(parsed);
                          }}
                          inputMode="decimal"
                          placeholder="e.g. 7.5"
                          className="w-full rounded-lg border border-white/10 bg-white/5 px-3 py-2 text-xs sm:text-sm theme-text-primary"
                        />
                      </div>
                    </div>
                  )}

                  {/* Discount Input */}
                  <div className="mb-3 sm:mb-4 pb-3 sm:pb-4 border-b border-white/10">
                    <label className="theme-text-secondary mb-2 block text-xs sm:text-sm font-medium">
                      Discount
                    </label>
                    <div className="flex gap-2">
                      <select
                        value={discountType}
                        onChange={(e) => {
                          setDiscountType(
                            e.target.value as "percent" | "amount",
                          );
                          setDiscountInput("");
                          setCartDiscount(0, 0, "");
                        }}
                        className="theme-surface rounded-lg border border-white/20 px-2 sm:px-3 py-2 text-xs sm:text-sm theme-text-primary focus:border-sky-400 focus:outline-none"
                      >
                        <option value="amount">₦</option>
                        <option value="percent">%</option>
                      </select>
                      <input
                        type="number"
                        value={discountInput}
                        onChange={(e) => {
                          const value = e.target.value;
                          setDiscountInput(value);
                          const numValue = parseFloat(value) || 0;
                          if (discountType === "percent") {
                            setCartDiscount(0, numValue, "Manual discount");
                          } else {
                            setCartDiscount(
                              Math.round(numValue * 100),
                              0,
                              "Manual discount",
                            );
                          }
                        }}
                        placeholder={discountType === "percent" ? "0" : "0.00"}
                        min="0"
                        step={discountType === "percent" ? "1" : "0.01"}
                        className="theme-surface flex-1 rounded-lg border border-white/20 px-3 sm:px-4 py-2 text-xs sm:text-sm theme-text-primary focus:border-sky-400 focus:outline-none"
                      />
                    </div>
                  </div>

                  <div className="space-y-2 sm:space-y-3 border-b border-white/10 pb-3 sm:pb-4">
                    <div className="flex justify-between text-xs sm:text-sm">
                      <span className="theme-text-secondary">Subtotal</span>
                      <span className="theme-text-primary">
                        {formatCurrency(finalSubtotal)}
                      </span>
                    </div>
                    {totalDiscount > 0 && (
                      <div className="flex justify-between text-xs sm:text-sm">
                        <span className="theme-text-secondary">Discount</span>
                        <span className="theme-text-primary text-emerald-400">
                          -{formatCurrency(totalDiscount)}
                        </span>
                      </div>
                    )}
                    {taxEnabled && tax > 0 && (
                      <div className="flex justify-between text-xs sm:text-sm">
                        <span className="theme-text-secondary">VAT</span>
                        <span className="theme-text-primary">
                          {formatCurrency(tax)}
                        </span>
                      </div>
                    )}
                  </div>

                  <div className="mt-3 sm:mt-4 mb-4 sm:mb-6 flex justify-between border-t border-white/10 pt-3 sm:pt-4">
                    <span className="theme-text-primary text-base sm:text-lg font-semibold">
                      Total
                    </span>
                    <span className="theme-text-primary text-lg sm:text-xl font-bold">
                      {formatCurrency(total)}
                    </span>
                  </div>

                  <div className="space-y-2">
                    <button
                      onClick={() => handlePaymentClick("cash")}
                      disabled={cart.length === 0 || isProcessing}
                      className="w-full rounded-xl bg-gradient-to-r from-emerald-500 to-green-600 px-4 sm:px-6 py-3 sm:py-3.5 text-sm sm:text-base font-semibold text-white shadow-lg transition hover:shadow-xl disabled:cursor-not-allowed disabled:opacity-50 touch-manipulation"
                    >
                      {isProcessing ? "Processing..." : "💵 Pay Cash"}
                    </button>
                    <button
                      onClick={() => handlePaymentClick("card")}
                      disabled={cart.length === 0 || isProcessing}
                      className="w-full rounded-xl bg-gradient-to-r from-blue-500 to-indigo-600 px-4 sm:px-6 py-3 sm:py-3.5 text-sm sm:text-base font-semibold text-white shadow-lg transition hover:shadow-xl disabled:cursor-not-allowed disabled:opacity-50 touch-manipulation"
                    >
                      💳 Pay Card
                    </button>
                    <button
                      onClick={() => handlePaymentClick("qr")}
                      disabled={cart.length === 0 || isProcessing}
                      className="w-full rounded-xl bg-gradient-to-r from-purple-500 to-pink-600 px-4 sm:px-6 py-3 sm:py-3.5 text-sm sm:text-base font-semibold text-white shadow-lg transition hover:shadow-xl disabled:cursor-not-allowed disabled:opacity-50 touch-manipulation"
                    >
                      📱 Pay QR
                    </button>
                    <button
                      onClick={() => handlePaymentClick("transfer")}
                      disabled={cart.length === 0 || isProcessing}
                      className="w-full rounded-xl bg-gradient-to-r from-amber-500 to-orange-600 px-4 sm:px-6 py-3 sm:py-3.5 text-sm sm:text-base font-semibold text-white shadow-lg transition hover:shadow-xl disabled:cursor-not-allowed disabled:opacity-50 touch-manipulation"
                    >
                      🏦 Pay Transfer
                    </button>
                    {(isAdmin || isManager) && (
                      <button
                        onClick={() => handlePaymentClick("credit")}
                        disabled={cart.length === 0 || isProcessing}
                        className="w-full rounded-xl bg-gradient-to-r from-yellow-500 to-amber-600 px-4 sm:px-6 py-3 sm:py-3.5 text-sm sm:text-base font-semibold text-white shadow-lg transition hover:shadow-xl disabled:cursor-not-allowed disabled:opacity-50 touch-manipulation"
                      >
                        💳 Credit Order
                      </button>
                    )}
                  </div>

                  {cart.length > 0 && (
                    <button
                      onClick={clearCart}
                      className="mt-3 sm:mt-4 w-full rounded-xl border border-white/20 bg-white/5 px-3 sm:px-4 py-2 text-xs sm:text-sm font-medium text-white/70 transition hover:bg-white/10 hover:text-white touch-manipulation"
                    >
                      Clear Cart
                    </button>
                  )}
                </div>
              </aside>
            </div>
          </div>
        </main>
      </div>

      <PaymentModal
        isOpen={paymentModalOpen}
        method={selectedPaymentMethod}
        total={total}
        cart={cart}
        customerName={selectedCustomer?.name || customerSearchQuery}
        customerEmail={selectedCustomer?.email}
        customerPhone={
          customerPhoneInput || selectedCustomer?.phone || undefined
        }
        onClose={() => {
          setPaymentModalOpen(false);
          setSelectedPaymentMethod(null);
        }}
        onComplete={async (change) => {
          if (change !== undefined) {
            setCashChange(change);
          }
          if (selectedPaymentMethod && selectedPaymentMethod !== "credit") {
            await handlePayment(selectedPaymentMethod);
          }
        }}
      />

      {/* Receipt Options Modal */}
      {lastCompletedOrderId && (
        <ReceiptOptionsModal
          isOpen={receiptOptionsOpen}
          orderId={lastCompletedOrderId}
          onClose={() => {
            setReceiptOptionsOpen(false);
            setLastCompletedOrderId(null);
          }}
        />
      )}

      {/* Quantity Selector Modal */}
      <QuantitySelectorModal
        isOpen={quantitySelectorOpen}
        product={selectedProduct}
        onClose={() => {
          setQuantitySelectorOpen(false);
          setSelectedProduct(null);
        }}
        onConfirm={handleQuantityConfirm}
      />
    </div>
  );
}

import { useState, useEffect, useCallback } from "react";
import { useAuthStore } from "../stores/authStore";
import axios from "axios";
import toast from "react-hot-toast";
import { format } from "date-fns";
import { API_URL } from "../config";
import { BrandMark } from "../components/BrandMark";
import { ThemeToggle } from "../components/ThemeToggle";

interface CreditOrder {
  id: string;
  uuid: string;
  orderNumber: string;
  locationId: string;
  customerId?: string;
  customer?: {
    id: string;
    name: string;
    email?: string;
    phone?: string;
  };
  items: Array<{
    productId: string;
    quantity: number;
    priceCents: number;
    taxCents: number;
    discountCents?: number;
    product?: {
      id: string;
      name: string;
      sku: string;
    };
  }>;
  subtotalCents: number;
  taxCents: number;
  discountCents: number;
  totalCents: number;
  status: string;
  paymentStatus?: string;
  isCreditOrder: boolean;
  createdAt: string;
  paidAt?: string;
  returnedAt?: string;
  createdBy: string;
  creator?: {
    id: string;
    name: string;
  };
  notes?: string;
}

export function CreditOrdersPage() {
  const { user, logout, accessToken } = useAuthStore();
  const [creditOrders, setCreditOrders] = useState<CreditOrder[]>([]);
  const [loading, setLoading] = useState(false);
  const [filterStatus, setFilterStatus] = useState<
    "all" | "pending" | "paid" | "returned"
  >("all");
  const [selectedOrder, setSelectedOrder] = useState<CreditOrder | null>(null);
  const [detailModalOpen, setDetailModalOpen] = useState(false);

  const loadCreditOrders = useCallback(async () => {
    if (!accessToken) {
      console.warn("Missing accessToken");
      return;
    }

    setLoading(true);
    try {
      if (!axios.defaults.headers.common["Authorization"]) {
        axios.defaults.headers.common["Authorization"] =
          `Bearer ${accessToken}`;
      }

      const response = await axios.get(`${API_URL}/api/v1/orders/credit`, {
        headers: {
          Authorization: `Bearer ${accessToken}`,
        },
      });

      const orders = response.data || [];

      console.log(`📦 Fetched ${orders.length} credit orders`);
      // Log customerIds from orders
      const orderCustomerIds = orders.map((o: CreditOrder) => ({
        orderId: o.id,
        orderNumber: o.orderNumber,
        customerId: o.customerId,
      }));
      console.log("📋 Orders with customerIds:", orderCustomerIds);

      // Fetch all users once for lookup
      const usersMap = new Map<string, any>();
      try {
        const usersResponse = await axios.get(`${API_URL}/api/v1/users`, {
          headers: { Authorization: `Bearer ${accessToken}` },
        });
        const users = usersResponse.data || [];
        users.forEach((user: any) => {
          usersMap.set(user.id, user);
        });
      } catch (error) {
        console.error("Failed to fetch users:", error);
        // Continue without user data
      }

      // Collect all unique customer IDs and fetch them individually
      const customerIds = [
        ...new Set(
          orders.map((order: CreditOrder) => order.customerId).filter(Boolean),
        ),
      ];
      const customersMap = new Map();

      console.log(
        `🔍 Fetching ${customerIds.length} unique customers for credit orders`,
      );

      // Fetch customers individually by ID (more reliable than fetching all and filtering)
      if (customerIds.length > 0) {
        await Promise.all(
          customerIds.map(async (customerId) => {
            try {
              console.log(`Fetching customer ${customerId}...`);
              const customerResponse = await axios.get(
                `${API_URL}/api/v1/customers/${customerId}`,
                { headers: { Authorization: `Bearer ${accessToken}` } },
              );
              if (customerResponse.data) {
                customersMap.set(customerId, customerResponse.data);
                console.log(
                  `✅ Found customer ${customerId}: ${customerResponse.data.name || "No name"}`,
                );
              } else {
                console.warn(`⚠️ Customer ${customerId} returned no data`);
              }
            } catch (err: any) {
              console.error(
                `❌ Failed to fetch customer ${customerId}:`,
                err.response?.status,
                err.response?.data || err.message,
              );
              // Don't throw - continue with other customers
            }
          }),
        );
      }

      console.log(
        `📊 Customer fetch complete. Found ${customersMap.size} out of ${customerIds.length} customers`,
      );

      // Fetch customer and product details for each order
      const enrichedOrders = await Promise.all(
        orders.map(async (order: CreditOrder) => {
          // Get customer from map if customerId exists
          const customer = order.customerId
            ? customersMap.get(order.customerId) || null
            : null;

          if (order.customerId) {
            if (!customer) {
              console.warn(
                `Customer ${order.customerId} not found in batch fetch, order: ${order.orderNumber}`,
              );
              console.log(
                "Available customer IDs in map:",
                Array.from(customersMap.keys()),
              );
              console.log("Order customerId:", order.customerId);
            } else {
              console.log(
                `Found customer for order ${order.orderNumber}:`,
                customer.name,
              );
            }
          } else {
            console.warn(`Order ${order.orderNumber} has no customerId`);
          }

          // Fetch product details for items
          const enrichedItems = await Promise.all(
            order.items.map(async (item) => {
              try {
                const productResponse = await axios.get(
                  `${API_URL}/api/v1/products/${item.productId}`,
                  { headers: { Authorization: `Bearer ${accessToken}` } },
                );
                return {
                  ...item,
                  product: productResponse.data,
                };
              } catch (error) {
                console.error(
                  `Failed to fetch product ${item.productId}:`,
                  error,
                );
                return item;
              }
            }),
          );

          // Get creator from users map
          const creator = usersMap.get(order.createdBy) || null;

          return {
            ...order,
            customer,
            items: enrichedItems,
            creator: creator
              ? {
                  id: creator.id,
                  name: creator.name,
                }
              : null,
          };
        }),
      );

      setCreditOrders(enrichedOrders);
    } catch (error: any) {
      console.error("Failed to load credit orders:", error);
      if (error.response?.status === 401) {
        toast.error("Authentication failed. Please log in again.");
      } else {
        toast.error(
          error.response?.data?.message || "Failed to load credit orders",
        );
      }
    } finally {
      setLoading(false);
    }
  }, [accessToken]);

  useEffect(() => {
    loadCreditOrders();
  }, [loadCreditOrders]);

  const handleMarkAsPaid = async (orderId: string) => {
    if (!accessToken) return;

    if (!confirm("Mark this credit order as paid?")) {
      return;
    }

    try {
      await axios.post(
        `${API_URL}/api/v1/orders/${orderId}/credit/mark-paid`,
        {},
        {
          headers: {
            Authorization: `Bearer ${accessToken}`,
          },
        },
      );

      toast.success("Credit order marked as paid");
      loadCreditOrders();
    } catch (error: any) {
      console.error("Failed to mark order as paid:", error);
      toast.error(
        error.response?.data?.message || "Failed to mark order as paid",
      );
    }
  };

  const handleMarkAsReturned = async (orderId: string) => {
    if (!accessToken) return;

    if (
      !confirm(
        "Mark this credit order as returned? This will restore inventory.",
      )
    ) {
      return;
    }

    try {
      await axios.post(
        `${API_URL}/api/v1/orders/${orderId}/credit/mark-returned`,
        {},
        {
          headers: {
            Authorization: `Bearer ${accessToken}`,
          },
        },
      );

      toast.success("Credit order marked as returned. Inventory restored.");
      loadCreditOrders();
    } catch (error: any) {
      console.error("Failed to mark order as returned:", error);
      toast.error(
        error.response?.data?.message || "Failed to mark order as returned",
      );
    }
  };

  const filteredOrders = creditOrders.filter((order) => {
    if (filterStatus === "all") return true;
    if (filterStatus === "pending")
      return order.paymentStatus === "pending" || !order.paymentStatus;
    if (filterStatus === "paid") return order.paymentStatus === "completed";
    if (filterStatus === "returned") return order.paymentStatus === "refunded";
    return true;
  });

  const pendingCount = creditOrders.filter(
    (o) => o.paymentStatus === "pending" || !o.paymentStatus,
  ).length;
  const paidCount = creditOrders.filter(
    (o) => o.paymentStatus === "completed",
  ).length;
  const returnedCount = creditOrders.filter(
    (o) => o.paymentStatus === "refunded",
  ).length;

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-950 via-slate-900 to-slate-950 text-white">
      {/* Header */}
      <header className="sticky top-0 z-50 border-b border-white/10 bg-slate-950/95 backdrop-blur-xl">
        <div className="mx-auto flex max-w-7xl items-center justify-between px-4 py-4 sm:px-6">
          <div className="flex items-center gap-4">
            <BrandMark className="h-8 w-8" />
            <div>
              <h1 className="text-xl font-bold sm:text-2xl">Credit Orders</h1>
              <p className="text-xs text-slate-400 sm:text-sm">
                Manage products taken on credit
              </p>
            </div>
          </div>
          <div className="flex items-center gap-2">
            <ThemeToggle />
            {user && (
              <button
                onClick={logout}
                className="rounded-lg bg-white/10 px-3 py-1.5 text-xs font-medium text-white transition hover:bg-white/20 sm:px-4 sm:py-2 sm:text-sm"
              >
                Logout
              </button>
            )}
          </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="mx-auto max-w-7xl px-4 py-6 sm:px-6 lg:px-8">
        {/* Filter Tabs */}
        <div className="mb-6 flex gap-2 overflow-x-auto pb-2">
          <button
            onClick={() => setFilterStatus("all")}
            className={`whitespace-nowrap rounded-lg px-4 py-2 text-sm font-medium transition ${
              filterStatus === "all"
                ? "bg-sky-500/20 text-sky-400 ring-1 ring-sky-500/30"
                : "bg-white/5 text-slate-400 hover:bg-white/10 hover:text-slate-300"
            }`}
          >
            All ({creditOrders.length})
          </button>
          <button
            onClick={() => setFilterStatus("pending")}
            className={`whitespace-nowrap rounded-lg px-4 py-2 text-sm font-medium transition ${
              filterStatus === "pending"
                ? "bg-yellow-500/20 text-yellow-400 ring-1 ring-yellow-500/30"
                : "bg-white/5 text-slate-400 hover:bg-white/10 hover:text-slate-300"
            }`}
          >
            Pending ({pendingCount})
          </button>
          <button
            onClick={() => setFilterStatus("paid")}
            className={`whitespace-nowrap rounded-lg px-4 py-2 text-sm font-medium transition ${
              filterStatus === "paid"
                ? "bg-green-500/20 text-green-400 ring-1 ring-green-500/30"
                : "bg-white/5 text-slate-400 hover:bg-white/10 hover:text-slate-300"
            }`}
          >
            Paid ({paidCount})
          </button>
          <button
            onClick={() => setFilterStatus("returned")}
            className={`whitespace-nowrap rounded-lg px-4 py-2 text-sm font-medium transition ${
              filterStatus === "returned"
                ? "bg-red-500/20 text-red-400 ring-1 ring-red-500/30"
                : "bg-white/5 text-slate-400 hover:bg-white/10 hover:text-slate-300"
            }`}
          >
            Returned ({returnedCount})
          </button>
        </div>

        {/* Orders List */}
        {loading ? (
          <div className="flex items-center justify-center py-12">
            <div className="h-12 w-12 animate-spin rounded-full border-b-2 border-sky-400"></div>
          </div>
        ) : filteredOrders.length === 0 ? (
          <div className="rounded-2xl border border-white/10 bg-white/5 p-12 text-center">
            <p className="text-lg font-medium text-slate-400">
              No credit orders found
            </p>
            <p className="mt-2 text-sm text-slate-500">
              {filterStatus !== "all"
                ? `No ${filterStatus} credit orders`
                : "Credit orders will appear here when products are taken on credit"}
            </p>
          </div>
        ) : (
          <div className="rounded-2xl border border-white/10 bg-white/5 p-4 sm:p-6">
            <div className="space-y-2">
              {filteredOrders.map((order) => {
                const isPending =
                  order.paymentStatus === "pending" || !order.paymentStatus;
                const isPaid = order.paymentStatus === "completed";
                const statusLabel = isPending
                  ? "Pending"
                  : isPaid
                    ? "Paid"
                    : "Returned";

                return (
                  <div
                    key={order.id}
                    className="flex items-center justify-between p-4 rounded-lg border border-white/10 hover:bg-white/5 transition"
                  >
                    <div className="flex items-center gap-4 flex-1 min-w-0">
                      <div className="flex-shrink-0 text-2xl">💳</div>
                      <div className="flex-1 min-w-0">
                        <div className="flex items-center gap-2 mb-1">
                          <p className="font-medium text-white truncate">
                            {order.orderNumber}
                          </p>
                          <span
                            className={`rounded-full px-2 py-0.5 text-xs font-medium ${
                              isPending
                                ? "bg-yellow-500/20 text-yellow-400"
                              : isPaid
                                ? "bg-green-500/20 text-green-400"
                                : "bg-red-500/20 text-red-400"
                            }`}
                          >
                            {statusLabel}
                          </span>
                          <span>Items: {order.items.length}</span>
                          <span>
                            {format(new Date(order.createdAt), "MMM dd, yyyy")}
                          </span>
                        </div>
                      </div>
                    </div>
                    <button
                      onClick={() => {
                        setSelectedOrder(order);
                        setDetailModalOpen(true);
                      }}
                      className="p-2 rounded-lg border border-white/10 hover:bg-white/10 text-white transition flex-shrink-0"
                      title="View Details"
                    >
                      <svg
                        className="w-5 h-5"
                        fill="none"
                        stroke="currentColor"
                        viewBox="0 0 24 24"
                      >
                        <path
                          strokeLinecap="round"
                          strokeLinejoin="round"
                          strokeWidth={2}
                          d="M15 12a3 3 0 11-6 0 3 3 0 016 0z"
                        />
                        <path
                          strokeLinecap="round"
                          strokeLinejoin="round"
                          strokeWidth={2}
                          d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z"
                        />
                      </svg>
                    </button>
                  </div>
                );
              })}
            </div>
          </div>
        )}
      </main>

      {/* Detail Modal */}
      {detailModalOpen && selectedOrder && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm p-4">
          <div className="w-full max-w-2xl max-h-[90vh] overflow-y-auto rounded-2xl border border-white/10 bg-slate-900 p-6">
            <div className="flex items-center justify-between mb-6">
              <h2 className="text-2xl font-bold text-white">Order Details</h2>
              <button
                onClick={() => {
                  setDetailModalOpen(false);
                  setSelectedOrder(null);
                }}
                className="p-2 rounded-lg border border-white/10 hover:bg-white/10 text-white transition"
              >
                <svg
                  className="w-5 h-5"
                  fill="none"
                  stroke="currentColor"
                  viewBox="0 0 24 24"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2}
                    d="M6 18L18 6M6 6l12 12"
                  />
                </svg>
              </button>
            </div>

            <div className="space-y-4">
              {/* Order Header */}
              <div className="flex flex-wrap items-center gap-3 pb-4 border-b border-white/10">
                <h3 className="text-xl font-semibold text-white">
                  {selectedOrder.orderNumber}
                </h3>
                <span
                  className={`rounded-full px-3 py-1 text-xs font-medium ${
                    selectedOrder.paymentStatus === "pending" ||
                    !selectedOrder.paymentStatus
                      ? "bg-yellow-500/20 text-yellow-400"
                      : selectedOrder.paymentStatus === "completed"
                        ? "bg-green-500/20 text-green-400"
                        : "bg-red-500/20 text-red-400"
                  }`}
                >
                  {selectedOrder.paymentStatus === "pending" ||
                  !selectedOrder.paymentStatus
                    ? "Pending Payment"
                    : selectedOrder.paymentStatus === "completed"
                      ? "Paid"
                      : "Returned"}
                </span>
              </div>

              {/* Customer Info */}
              {selectedOrder.customerId && (
                <div className="p-4 rounded-lg bg-white/5">
                  <h4 className="text-sm font-semibold text-slate-300 mb-2">
                    Customer Information
                  </h4>
                  {selectedOrder.customer ? (
                    <div className="space-y-1 text-sm text-slate-400">
                      <p>
                        <span className="font-medium">Name:</span>{" "}
                        {selectedOrder.customer.name}
                      </p>
                      {selectedOrder.customer.phone && (
                        <p>
                          <span className="font-medium">Phone:</span>{" "}
                          {selectedOrder.customer.phone}
                        </p>
                      )}
                      {selectedOrder.customer.email && (
                        <p>
                          <span className="font-medium">Email:</span>{" "}
                          {selectedOrder.customer.email}
                        </p>
                      )}
                    </div>
                  ) : (
                    <p className="text-sm text-slate-500 italic">
                      Customer ID: {selectedOrder.customerId}
                    </p>
                  )}
                </div>
              )}

              {/* Order Info */}
              <div className="grid grid-cols-2 gap-4 text-sm">
                {selectedOrder.creator && (
                  <div>
                    <span className="text-slate-400">Created by:</span>
                    <p className="text-white font-medium">
                      {selectedOrder.creator.name}
                    </p>
                  </div>
                )}
                <div>
                  <span className="text-slate-400">Collected on:</span>
                  <p className="text-white font-medium">
                    {format(
                      new Date(selectedOrder.createdAt),
                      "MMM dd, yyyy HH:mm",
                    )}
                  </p>
                </div>
                {/* Only show paid date if status is completed AND paidAt exists AND is different from createdAt */}
                {selectedOrder.paymentStatus === "completed" &&
                  selectedOrder.paidAt &&
                  new Date(selectedOrder.paidAt).getTime() !==
                    new Date(selectedOrder.createdAt).getTime() && (
                    <div>
                      <span className="text-slate-400">Paid on:</span>
                      <p className="text-green-400 font-medium">
                        {format(
                          new Date(selectedOrder.paidAt),
                          "MMM dd, yyyy HH:mm",
                        )}
                      </p>
                    </div>
                  )}
                {/* Only show returned date if status is refunded AND returnedAt exists AND is different from createdAt */}
                {selectedOrder.paymentStatus === "refunded" &&
                  selectedOrder.returnedAt &&
                  new Date(selectedOrder.returnedAt).getTime() !==
                    new Date(selectedOrder.createdAt).getTime() && (
                    <div>
                      <span className="text-slate-400">Returned on:</span>
                      <p className="text-red-400 font-medium">
                        {format(
                          new Date(selectedOrder.returnedAt),
                          "MMM dd, yyyy HH:mm",
                        )}
                      </p>
                    </div>
                  )}
              </div>

              {/* Items */}
              <div className="rounded-lg bg-white/5 p-4">
                <h4 className="text-sm font-semibold text-slate-300 mb-3">
                  Items
                </h4>
                <div className="space-y-2">
                  {selectedOrder.items.map((item, idx) => (
                    <div
                      key={idx}
                      className="flex justify-between items-center py-2 border-b border-white/5 last:border-0"
                    >
                      <div className="flex-1">
                        <p className="text-white font-medium">
                          {item.product?.name || `Product ${item.productId}`}
                        </p>
                        <p className="text-sm text-slate-400">
                          Qty: {item.quantity} × ₦
                          {(item.priceCents / 100).toFixed(2)}
                        </p>
                      </div>
                      <p className="text-white font-semibold">
                        ₦{((item.priceCents * item.quantity) / 100).toFixed(2)}
                      </p>
                    </div>
                  ))}
                </div>
                <div className="mt-4 pt-4 border-t border-white/10">
                  <div className="flex justify-between items-center">
                    <span className="text-slate-400">Subtotal:</span>
                    <span className="text-white font-medium">
                      ₦{(selectedOrder.subtotalCents / 100).toFixed(2)}
                    </span>
                  </div>
                  {selectedOrder.taxCents > 0 && (
                    <div className="flex justify-between items-center mt-1">
                      <span className="text-slate-400">Tax:</span>
                      <span className="text-white font-medium">
                        ₦{(selectedOrder.taxCents / 100).toFixed(2)}
                      </span>
                    </div>
                  )}
                  {selectedOrder.discountCents > 0 && (
                    <div className="flex justify-between items-center mt-1">
                      <span className="text-slate-400">Discount:</span>
                      <span className="text-white font-medium">
                        -₦{(selectedOrder.discountCents / 100).toFixed(2)}
                      </span>
                    </div>
                  )}
                  <div className="flex justify-between items-center mt-3 pt-3 border-t border-white/10">
                    <span className="text-lg font-semibold text-white">
                      Total:
                    </span>
                    <span className="text-xl font-bold text-white">
                      ₦{(selectedOrder.totalCents / 100).toFixed(2)}
                    </span>
                  </div>
                </div>
              </div>

              {/* Notes */}
              {selectedOrder.notes && (
                <div className="p-4 rounded-lg bg-white/5">
                  <h4 className="text-sm font-semibold text-slate-300 mb-2">
                    Notes
                  </h4>
                  <p className="text-sm text-slate-400">
                    {selectedOrder.notes}
                  </p>
                </div>
              )}

              {/* Actions */}
              {(selectedOrder.paymentStatus === "pending" ||
                !selectedOrder.paymentStatus) && (
                <div className="flex gap-3 pt-4 border-t border-white/10">
                  <button
                    onClick={() => {
                      handleMarkAsPaid(selectedOrder.id);
                      setDetailModalOpen(false);
                      setSelectedOrder(null);
                    }}
                    className="flex-1 rounded-lg bg-green-500/20 px-4 py-2 text-sm font-medium text-green-400 transition hover:bg-green-500/30"
                  >
                    Mark as Paid
                  </button>
                  <button
                    onClick={() => {
                      handleMarkAsReturned(selectedOrder.id);
                      setDetailModalOpen(false);
                      setSelectedOrder(null);
                    }}
                    className="flex-1 rounded-lg bg-red-500/20 px-4 py-2 text-sm font-medium text-red-400 transition hover:bg-red-500/30"
                  >
                    Mark as Returned
                  </button>
                </div>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

import { useState, useEffect, useCallback } from "react";
import { useAuthStore } from "../stores/authStore";
import axios from "axios";
import toast from "react-hot-toast";
import { Link, useSearchParams } from "react-router-dom";
import { format } from "date-fns";
import { API_URL } from "../config";
import { BrandMark } from "../components/BrandMark";
import { ThemeToggle } from "../components/ThemeToggle";

interface PurchaseOrder {
  id: string;
  supplierId: string;
  supplierName: string;
  orderNumber: string;
  status: string;
  items: Array<{
    productId: string;
    productName: string;
    sku: string;
    quantity: number;
    unitCostCents: number;
    totalCostCents: number;
    receivedQuantity?: number;
  }>;
  subtotalCents: number;
  taxCents: number;
  totalCents: number;
  expectedDeliveryDate?: string;
  notes?: string;
}

interface GRNItem {
  productId: string;
  productName: string;
  sku: string;
  orderedQuantity: number;
  receivedQuantity: number;
  batchNumber?: string;
  expiryDate?: string;
  unitCostCents: number;
  totalCostCents: number;
}

export function GRNPage() {
  const { logout, accessToken } = useAuthStore();
  const [searchParams] = useSearchParams();
  const poIdFromUrl = searchParams.get("poId");

  const [purchaseOrders, setPurchaseOrders] = useState<PurchaseOrder[]>([]);
  const [selectedPO, setSelectedPO] = useState<PurchaseOrder | null>(null);
  const [loading, setLoading] = useState(false);
  const [submitting, setSubmitting] = useState(false);

  const [grnItems, setGrnItems] = useState<GRNItem[]>([]);
  const [formData, setFormData] = useState({
    notes: "",
  });

  const initializeGRNItems = useCallback((po: PurchaseOrder) => {
    const items: GRNItem[] = po.items.map((item) => {
      const alreadyReceived = item.receivedQuantity || 0;
      const remaining = item.quantity - alreadyReceived;
      return {
        productId: item.productId,
        productName: item.productName,
        sku: item.sku,
        orderedQuantity: item.quantity,
        receivedQuantity: remaining > 0 ? remaining : 0,
        batchNumber: "",
        expiryDate: "",
        unitCostCents: item.unitCostCents,
        totalCostCents: item.unitCostCents * (remaining > 0 ? remaining : 0),
      };
    });
    setGrnItems(items);
  }, []);

  const loadPurchaseOrders = useCallback(async () => {
    if (!accessToken) return;
    setLoading(true);
    try {
      const response = await axios.get(`${API_URL}/api/v1/purchase-orders`, {
        headers: { Authorization: `Bearer ${accessToken}` },
      });
      // Filter for approved or partially received POs
      const approvedPOs = (response.data || []).filter(
        (po: PurchaseOrder) =>
          po.status === "approved" || po.status === "partially_received",
      );
      setPurchaseOrders(approvedPOs);

      // If poId is in URL, select that PO
      if (poIdFromUrl) {
        const po = approvedPOs.find((p: PurchaseOrder) => p.id === poIdFromUrl);
        if (po) {
          setSelectedPO(po);
          initializeGRNItems(po);
        }
      }
    } catch (error: any) {
      console.error("Failed to load purchase orders:", error);
      if (error.response?.status !== 401) {
        toast.error("Failed to load purchase orders");
      }
    } finally {
      setLoading(false);
    }
  }, [accessToken, poIdFromUrl, initializeGRNItems]);

  const loadPurchaseOrder = useCallback(
    async (poId: string) => {
      if (!accessToken) return;
      try {
        const response = await axios.get(
          `${API_URL}/api/v1/purchase-orders/${poId}`,
          {
            headers: { Authorization: `Bearer ${accessToken}` },
          },
        );
        setSelectedPO(response.data);
        initializeGRNItems(response.data);
      } catch (error: any) {
        console.error("Failed to load purchase order:", error);
        toast.error("Failed to load purchase order");
      }
    },
    [accessToken, initializeGRNItems],
  );

  useEffect(() => {
    if (accessToken) {
      loadPurchaseOrders();
    }
  }, [accessToken, loadPurchaseOrders]);

  useEffect(() => {
    if (poIdFromUrl && accessToken && purchaseOrders.length > 0) {
      const po = purchaseOrders.find((p) => p.id === poIdFromUrl);
      if (po) {
        setSelectedPO(po);
        initializeGRNItems(po);
      } else {
        // PO not in list, try to load it directly
        loadPurchaseOrder(poIdFromUrl);
      }
    }
  }, [poIdFromUrl, accessToken, purchaseOrders, initializeGRNItems, loadPurchaseOrder]);

  const updateGRNItem = (index: number, field: string, value: any) => {
    const newItems = [...grnItems];
    const item = { ...newItems[index] };

    if (field === "receivedQuantity") {
      const qty = parseFloat(value) || 0;
      const maxQty =
        item.orderedQuantity -
        (selectedPO?.items.find((i) => i.productId === item.productId)
          ?.receivedQuantity || 0);
      item.receivedQuantity = Math.min(Math.max(0, qty), maxQty);
      item.totalCostCents = item.receivedQuantity * item.unitCostCents;
    } else if (field === "batchNumber" || field === "expiryDate") {
      item[field] = value;
    }

    newItems[index] = item;
    setGrnItems(newItems);
  };

  const calculateTotals = () => {
    const subtotal = grnItems.reduce(
      (sum, item) => sum + item.totalCostCents,
      0,
    );
    const tax = Math.round(subtotal * 0.075); // 7.5% tax
    const total = subtotal + tax;
    return { subtotal, tax, total };
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!accessToken || !selectedPO) {
      toast.error("Not authenticated or no PO selected");
      return;
    }

    // Validate that at least one item has received quantity > 0
    const hasReceivedItems = grnItems.some((item) => item.receivedQuantity > 0);
    if (!hasReceivedItems) {
      toast.error("Please enter received quantities for at least one item");
      return;
    }

    // Validate received quantities don't exceed ordered
    for (const item of grnItems) {
      if (item.receivedQuantity > 0) {
        const poItem = selectedPO.items.find(
          (i) => i.productId === item.productId,
        );
        const alreadyReceived = poItem?.receivedQuantity || 0;
        const maxAllowed = (poItem?.quantity || 0) - alreadyReceived;
        if (item.receivedQuantity > maxAllowed) {
          toast.error(
            `${item.productName}: Received quantity cannot exceed remaining ordered quantity`,
          );
          return;
        }
      }
    }

    setSubmitting(true);
    try {
      const { subtotal, tax, total } = calculateTotals();

      const response = await axios.post(
        `${API_URL}/api/v1/grn`,
        {
          purchaseOrderId: selectedPO.id,
          items: grnItems
            .filter((item) => item.receivedQuantity > 0)
            .map((item) => ({
              productId: item.productId,
              productName: item.productName,
              sku: item.sku,
              orderedQuantity: item.orderedQuantity,
              receivedQuantity: item.receivedQuantity,
              batchNumber: item.batchNumber || undefined,
              expiryDate: item.expiryDate || undefined,
              unitCostCents: item.unitCostCents,
              totalCostCents: item.totalCostCents,
            })),
          subtotalCents: subtotal,
          taxCents: tax,
          totalCents: total,
          notes: formData.notes || undefined,
        },
        { headers: { Authorization: `Bearer ${accessToken}` } },
      );

      // Show notifications based on response metadata
      const metadata = (response.data as any)?.metadata;
      if (metadata) {
        if (metadata.newProductsCount > 0) {
          toast.success(
            `✅ ${metadata.newProductsCount} new product${metadata.newProductsCount > 1 ? "s" : ""} added to inventory!`,
            {
              duration: 5000,
            },
          );
        }
        if (metadata.restockedProductsCount > 0) {
          toast.success(
            `📦 ${metadata.restockedProductsCount} product${metadata.restockedProductsCount > 1 ? "s" : ""} restocked!`,
            {
              duration: 5000,
            },
          );
        }
      } else {
        toast.success("GRN created successfully! Inventory updated.");
      }

      // Reset form
      setSelectedPO(null);
      setGrnItems([]);
      setFormData({ notes: "" });

      // Reload purchase orders
      await loadPurchaseOrders();
    } catch (error: any) {
      console.error("Failed to create GRN:", error);
      toast.error(error.response?.data?.message || "Failed to create GRN");
    } finally {
      setSubmitting(false);
    }
  };

  const formatCurrency = (cents: number) => {
    return `₦${(cents / 100).toFixed(2)}`;
  };

  return (
    <div className="theme-background min-h-screen w-full overflow-x-hidden page-with-nav">
      <div className="relative mx-auto w-full max-w-7xl space-y-4 sm:space-y-6 px-3 sm:px-4 lg:px-6 py-4 sm:py-6 lg:py-10">
        {/* Header */}
        <div className="theme-card flex flex-col gap-4 sm:gap-6 rounded-xl sm:rounded-2xl lg:rounded-3xl border p-4 sm:p-5 lg:p-6 backdrop-blur-xl md:flex-row md:items-center md:justify-between">
          <div className="flex items-start gap-3 sm:gap-4 min-w-0">
            <BrandMark
              size={40}
              backgroundClassName="bg-white/90 dark:bg-white/10"
              className="ring-1 ring-slate-200/40 dark:ring-white/10 flex-shrink-0 sm:w-[56px] sm:h-[56px]"
            />
            <div className="min-w-0 flex-1">
              <p className="theme-text-secondary text-[10px] sm:text-xs uppercase tracking-[0.35em]">
                Goods Received Note
              </p>
              <h1 className="theme-text-primary text-xl sm:text-2xl lg:text-3xl font-semibold tracking-tight">
                Receive Items
              </h1>
              <p className="theme-text-secondary text-xs sm:text-sm">
                Receive items from approved purchase orders
              </p>
            </div>
          </div>
          <div className="flex flex-wrap items-center gap-2 sm:gap-3">
            <Link
              to="/purchase-orders"
              className="theme-chip inline-flex items-center gap-2 rounded-full border px-5 py-2 text-sm font-semibold transition"
            >
              📋 Purchase Orders
            </Link>
            <Link
              to="/suppliers"
              className="theme-chip inline-flex items-center gap-2 rounded-full border px-5 py-2 text-sm font-semibold transition"
            >
              🏢 Suppliers
            </Link>
            <Link
              to="/inventory"
              className="theme-chip inline-flex items-center gap-2 rounded-full border px-5 py-2 text-sm font-semibold transition"
            >
              📦 Inventory
            </Link>
            <Link
              to="/checkout"
              className="theme-chip inline-flex items-center gap-2 rounded-full border px-5 py-2 text-sm font-semibold transition"
            >
              🛒 Checkout
            </Link>
            <button
              onClick={logout}
              className="inline-flex items-center gap-2 rounded-full bg-gradient-to-r from-rose-400 via-pink-500 to-rose-500 px-5 py-2 text-sm font-semibold text-white shadow-lg transition"
            >
              Logout
            </button>
            <ThemeToggle />
          </div>
        </div>

        {/* Select Purchase Order */}
        {!selectedPO && (
          <div className="theme-card rounded-3xl border p-6 backdrop-blur-xl">
            <h2 className="theme-text-primary text-xl font-semibold mb-4">
              Select Purchase Order
            </h2>
            {loading ? (
              <p className="theme-text-secondary text-sm">
                Loading purchase orders...
              </p>
            ) : purchaseOrders.length === 0 ? (
              <div className="theme-surface rounded-2xl border border-dashed p-12 text-center">
                <p className="theme-text-primary text-lg font-semibold">
                  No approved purchase orders found
                </p>
                <p className="theme-text-secondary mt-2 text-sm">
                  Purchase orders must be approved before items can be received.
                </p>
                <Link
                  to="/purchase-orders"
                  className="mt-4 inline-block rounded-full bg-gradient-to-r from-emerald-400 via-emerald-500 to-emerald-400 px-6 py-3 text-base font-semibold text-emerald-950 shadow-lg transition hover:shadow-emerald-900/70"
                >
                  Go to Purchase Orders
                </Link>
              </div>
            ) : (
              <div className="space-y-3">
                {purchaseOrders.map((po) => (
                  <div
                    key={po.id}
                    onClick={() => {
                      setSelectedPO(po);
                      initializeGRNItems(po);
                    }}
                    className="theme-surface rounded-xl border border-white/10 p-4 cursor-pointer hover:border-sky-400/50 transition"
                  >
                    <div className="flex items-start justify-between">
                      <div className="flex-1">
                        <h3 className="theme-text-primary text-lg font-semibold mb-1">
                          {po.orderNumber}
                        </h3>
                        <p className="theme-text-secondary text-sm mb-2">
                          Supplier:{" "}
                          <span className="font-semibold">
                            {po.supplierName}
                          </span>
                        </p>
                        <div className="grid gap-2 sm:grid-cols-3 text-sm">
                          <div>
                            <span className="theme-text-secondary">
                              Items:{" "}
                            </span>
                            <span className="theme-text-primary font-semibold">
                              {po.items.length}
                            </span>
                          </div>
                          <div>
                            <span className="theme-text-secondary">
                              Total:{" "}
                            </span>
                            <span className="theme-text-primary font-semibold">
                              {formatCurrency(po.totalCents)}
                            </span>
                          </div>
                          {po.expectedDeliveryDate && (
                            <div>
                              <span className="theme-text-secondary">
                                Expected:{" "}
                              </span>
                              <span className="theme-text-primary font-semibold">
                                {format(
                                  new Date(po.expectedDeliveryDate),
                                  "MMM d, yyyy",
                                )}
                              </span>
                            </div>
                          )}
                        </div>
                      </div>
                      <button className="ml-4 rounded-full bg-gradient-to-r from-emerald-400 via-emerald-500 to-emerald-400 px-6 py-2 text-sm font-semibold text-emerald-950 shadow-lg transition hover:shadow-emerald-900/70">
                        Receive Items
                      </button>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}

        {/* GRN Form */}
        {selectedPO && (
          <div className="theme-card rounded-3xl border p-6 backdrop-blur-xl">
            <div className="flex items-center justify-between mb-4">
              <div>
                <h2 className="theme-text-primary text-xl font-semibold">
                  Create GRN
                </h2>
                <p className="theme-text-secondary text-sm mt-1">
                  PO: {selectedPO.orderNumber} • Supplier:{" "}
                  {selectedPO.supplierName}
                </p>
              </div>
              <button
                onClick={() => {
                  setSelectedPO(null);
                  setGrnItems([]);
                  setFormData({ notes: "" });
                }}
                className="rounded-full border border-white/20 bg-transparent px-4 py-2 text-sm font-semibold theme-text-primary transition hover:bg-white/5"
              >
                Change PO
              </button>
            </div>

            <form onSubmit={handleSubmit} className="space-y-4">
              {/* Items */}
              <div className="space-y-3">
                <h3 className="theme-text-primary text-lg font-semibold">
                  Items to Receive
                </h3>
                {grnItems.length === 0 ? (
                  <p className="theme-text-secondary text-sm text-center py-4">
                    No items to receive.
                  </p>
                ) : (
                  <div className="space-y-3">
                    {grnItems.map((item, index) => {
                      const poItem = selectedPO.items.find(
                        (i) => i.productId === item.productId,
                      );
                      const alreadyReceived = poItem?.receivedQuantity || 0;
                      const maxAllowed =
                        (poItem?.quantity || 0) - alreadyReceived;

                      return (
                        <div
                          key={index}
                          className="theme-surface rounded-xl border border-white/10 p-4"
                        >
                          <div className="mb-3">
                            <h4 className="theme-text-primary font-semibold">
                              {item.productName}
                            </h4>
                            <p className="theme-text-secondary text-xs">
                              SKU: {item.sku} • Ordered: {item.orderedQuantity}
                              {alreadyReceived > 0 && (
                                <span className="ml-2">
                                  • Already Received: {alreadyReceived}
                                </span>
                              )}
                              {maxAllowed > 0 && (
                                <span className="ml-2 text-emerald-400">
                                  • Remaining: {maxAllowed}
                                </span>
                              )}
                            </p>
                          </div>
                          <div className="grid gap-3 sm:grid-cols-12">
                            <div className="sm:col-span-3">
                              <label className="block text-xs font-medium theme-text-secondary mb-1">
                                Received Qty *
                              </label>
                              <input
                                type="number"
                                min="0"
                                max={maxAllowed}
                                step="1"
                                value={item.receivedQuantity}
                                onChange={(e) =>
                                  updateGRNItem(
                                    index,
                                    "receivedQuantity",
                                    e.target.value,
                                  )
                                }
                                className="w-full theme-surface rounded-lg border border-white/20 bg-transparent px-3 py-2 text-sm theme-text-primary focus:border-sky-400 focus:outline-none"
                                required={item.receivedQuantity > 0}
                              />
                            </div>
                            <div className="sm:col-span-3">
                              <label className="block text-xs font-medium theme-text-secondary mb-1">
                                Batch Number
                              </label>
                              <input
                                type="text"
                                value={item.batchNumber}
                                onChange={(e) =>
                                  updateGRNItem(
                                    index,
                                    "batchNumber",
                                    e.target.value,
                                  )
                                }
                                className="w-full theme-surface rounded-lg border border-white/20 bg-transparent px-3 py-2 text-sm theme-text-primary focus:border-sky-400 focus:outline-none"
                                placeholder="Optional"
                              />
                            </div>
                            <div className="sm:col-span-3">
                              <label className="block text-xs font-medium theme-text-secondary mb-1">
                                Expiry Date
                              </label>
                              <input
                                type="date"
                                value={item.expiryDate}
                                onChange={(e) =>
                                  updateGRNItem(
                                    index,
                                    "expiryDate",
                                    e.target.value,
                                  )
                                }
                                className="w-full theme-surface rounded-lg border border-white/20 bg-transparent px-3 py-2 text-sm theme-text-primary focus:border-sky-400 focus:outline-none"
                              />
                            </div>
                            <div className="sm:col-span-2">
                              <label className="block text-xs font-medium theme-text-secondary mb-1">
                                Unit Cost
                              </label>
                              <input
                                type="text"
                                value={formatCurrency(item.unitCostCents)}
                                readOnly
                                className="w-full theme-surface rounded-lg border border-white/20 bg-transparent px-3 py-2 text-sm theme-text-primary opacity-60"
                              />
                            </div>
                            <div className="sm:col-span-1">
                              <label className="block text-xs font-medium theme-text-secondary mb-1">
                                Total
                              </label>
                              <input
                                type="text"
                                value={formatCurrency(item.totalCostCents)}
                                readOnly
                                className="w-full theme-surface rounded-lg border border-white/20 bg-transparent px-3 py-2 text-sm theme-text-primary opacity-60"
                              />
                            </div>
                          </div>
                        </div>
                      );
                    })}
                  </div>
                )}
              </div>

              {/* Notes */}
              <div>
                <label className="block text-sm font-medium theme-text-secondary mb-1">
                  Notes
                </label>
                <textarea
                  value={formData.notes}
                  onChange={(e) =>
                    setFormData({ ...formData, notes: e.target.value })
                  }
                  className="w-full theme-surface rounded-lg border border-white/20 bg-transparent px-4 py-3 text-base theme-text-primary focus:border-sky-400 focus:outline-none"
                  rows={2}
                  placeholder="Additional notes..."
                />
              </div>

              {/* Totals */}
              {grnItems.some((item) => item.receivedQuantity > 0) && (
                <div className="theme-surface rounded-xl border border-white/10 p-4">
                  <div className="flex justify-end">
                    <div className="w-full max-w-xs space-y-2">
                      <div className="flex justify-between text-sm">
                        <span className="theme-text-secondary">Subtotal:</span>
                        <span className="theme-text-primary font-semibold">
                          {formatCurrency(calculateTotals().subtotal)}
                        </span>
                      </div>
                      <div className="flex justify-between text-sm">
                        <span className="theme-text-secondary">
                          Tax (7.5%):
                        </span>
                        <span className="theme-text-primary font-semibold">
                          {formatCurrency(calculateTotals().tax)}
                        </span>
                      </div>
                      <div className="flex justify-between border-t border-white/10 pt-2 text-base">
                        <span className="theme-text-primary font-semibold">
                          Total:
                        </span>
                        <span className="theme-text-primary font-bold">
                          {formatCurrency(calculateTotals().total)}
                        </span>
                      </div>
                    </div>
                  </div>
                </div>
              )}

              <div className="flex gap-3">
                <button
                  type="submit"
                  disabled={
                    submitting ||
                    !grnItems.some((item) => item.receivedQuantity > 0)
                  }
                  className="flex-1 rounded-full bg-gradient-to-r from-emerald-400 via-emerald-500 to-emerald-400 px-6 py-3 text-base font-semibold text-emerald-950 shadow-lg transition hover:shadow-emerald-900/70 disabled:opacity-50 disabled:cursor-not-allowed"
                >
                  {submitting
                    ? "Creating GRN..."
                    : "Create GRN & Update Inventory"}
                </button>
                <button
                  type="button"
                  onClick={() => {
                    setSelectedPO(null);
                    setGrnItems([]);
                    setFormData({ notes: "" });
                  }}
                  className="rounded-full border border-white/20 bg-transparent px-6 py-3 text-base font-semibold theme-text-primary transition hover:bg-white/5"
                >
                  Cancel
                </button>
              </div>
            </form>
          </div>
        )}
      </div>
    </div>
  );
}

import { useState, useEffect, useCallback } from "react";
import { useAuthStore } from "../stores/authStore";
import { BarcodeScanner } from "../components/BarcodeScanner";
import { ScannerDeviceList } from "../components/ScannerDeviceList";
import axios from "axios";
import toast from "react-hot-toast";
import { Link } from "react-router-dom";
import { API_URL } from "../config";
import { BrandMark } from "../components/BrandMark";
import { ThemeToggle } from "../components/ThemeToggle";

interface InventoryItem {
  id: string;
  productId: string;
  product: {
    id: string;
    name: string;
    sku: string;
    barcode?: string;
    priceCents?: number;
  };
  quantity: number;
  reorderPoint?: number;
  costCents?: number;
  salesPriceCents?: number;
  isProductMissing?: boolean;
}

export function InventoryPage() {
  const { user, logout, accessToken } = useAuthStore();
  const [inventory, setInventory] = useState<InventoryItem[]>([]);
  const [loading, setLoading] = useState(false);
  const [selectedProduct, setSelectedProduct] = useState<any>(null);
  const [adjustQuantity, setAdjustQuantity] = useState("");
  const [adjustType, setAdjustType] = useState<"adjust" | "received">("adjust");
  const [effectiveLocationId, setEffectiveLocationId] = useState<string | null>(
    user?.locationId || null,
  );
  const [editingItem, setEditingItem] = useState<{
    productId: string;
    quantity: string;
    reorderPoint: string;
    costCents: string;
    salesPriceCents: string;
  } | null>(null);
  const hasMissingProducts = inventory.some((item) => item.isProductMissing);

  // Get the effective locationId (user's locationId or first location for tenant)
  const getEffectiveLocationId = useCallback(async (): Promise<string | null> => {
    if (!accessToken || !user) return null;

    if (user.locationId) {
      return user.locationId;
    }

    try {
      const response = await axios.get(`${API_URL}/api/v1/locations`, {
        headers: { Authorization: `Bearer ${accessToken}` },
      });
      const locations = response.data || [];
      if (locations.length > 0) {
        return locations[0].id;
      }
    } catch (error) {
      console.error("Failed to fetch locations:", error);
    }

    return null;
  }, [accessToken, user]);

  const loadInventory = useCallback(async () => {
    if (!accessToken || !user) return;

    setLoading(true);
    try {
      // Get effective locationId
      const locationId = await getEffectiveLocationId();
      if (!locationId) {
        setInventory([]);
        toast.error("No location found. Please set your location in Settings.");
        return;
      }

      setEffectiveLocationId(locationId);

      const response = await axios.get(
        `${API_URL}/api/v1/inventory/${locationId}/stock`,
        { headers: { Authorization: `Bearer ${accessToken}` } },
      );
      setInventory(response.data || []);
    } catch (error: any) {
      console.error("Failed to load inventory:", error);
      if (error.response?.status === 401) {
        toast.error("Authentication expired. Please log in again.");
      } else {
        toast.error(
          error.response?.data?.message || "Failed to load inventory",
        );
      }
    } finally {
      setLoading(false);
    }
  }, [accessToken, user, getEffectiveLocationId]);

  const handleScan = async (barcode: string) => {
    if (!accessToken) {
      toast.error("Not authenticated");
      return;
    }

    try {
      // Find product by barcode
      const productResponse = await axios.get(
        `${API_URL}/api/v1/products?query=${encodeURIComponent(barcode)}`,
        { headers: { Authorization: `Bearer ${accessToken}` } },
      );

      if (productResponse.data && productResponse.data.length > 0) {
        const product = productResponse.data[0];
        setSelectedProduct(product);

        // Get effective locationId
        const locationId =
          effectiveLocationId || (await getEffectiveLocationId());
        if (!locationId) {
          toast.error("Location not set");
          return;
        }

        const invResponse = await axios.get(
          `${API_URL}/api/v1/inventory/${locationId}/stock`,
          { headers: { Authorization: `Bearer ${accessToken}` } },
        );

        const invItem = invResponse.data.find(
          (inv: any) => inv.productId === product.id,
        );
        if (invItem) {
          setAdjustQuantity(invItem.quantity.toString());
        } else {
          setAdjustQuantity("0");
        }
      } else {
        toast.error(`Product not found: ${barcode}`);
      }
    } catch (error: any) {
      toast.error(error.response?.data?.message || "Failed to find product");
    }
  };

  const handleAdjustInventory = async () => {
    if (!selectedProduct || !adjustQuantity || !accessToken || !user) {
      toast.error("Please select a product and enter quantity");
      return;
    }

    try {
      // Get effective locationId
      const locationId =
        effectiveLocationId || (await getEffectiveLocationId());
      if (!locationId) {
        toast.error("Location not set. Please set your location in Settings.");
        return;
      }

      // Find current inventory
      const invResponse = await axios.get(
        `${API_URL}/api/v1/inventory/${locationId}/stock`,
        { headers: { Authorization: `Bearer ${accessToken}` } },
      );

      const invItem = invResponse.data.find(
        (inv: any) => inv.productId === selectedProduct.id,
      );
      const currentQty = invItem?.quantity || 0;
      const newQty = parseInt(adjustQuantity, 10);
      const delta = newQty - currentQty;

      if (delta === 0) {
        toast("No change needed", { icon: "ℹ️" });
        return;
      }

      await axios.post(
        `${API_URL}/api/v1/inventory/adjust`,
        {
          productId: selectedProduct.id,
          locationId,
          delta,
          type: adjustType,
          userId: user.id,
          notes: `Manual adjustment via POS`,
        },
        { headers: { Authorization: `Bearer ${accessToken}` } },
      );

      toast.success(
        `Inventory updated: ${selectedProduct.name} = ${newQty} units`,
      );
      setSelectedProduct(null);
      setAdjustQuantity("");
      loadInventory();
    } catch (error: any) {
      toast.error(
        error.response?.data?.message || "Failed to adjust inventory",
      );
    }
  };

  const handleUpdateItem = async (productId: string) => {
    if (!editingItem || !accessToken) return;

    try {
      // Validate required fields
      if (!editingItem.costCents || !editingItem.salesPriceCents) {
        toast.error("Cost price and selling price are required");
        return;
      }

      const costCents = Math.round(parseFloat(editingItem.costCents) * 100);
      const salesPriceCents = Math.round(
        parseFloat(editingItem.salesPriceCents) * 100,
      );

      if (
        isNaN(costCents) ||
        costCents < 0 ||
        isNaN(salesPriceCents) ||
        salesPriceCents < 0
      ) {
        toast.error("Invalid price values");
        return;
      }

      // Get current inventory to preserve values if not being updated
      const currentItem = inventory.find((inv) => inv.productId === productId);

      // Don't send locationId - let backend resolve it from user context
      // This avoids UUID validation errors
      await axios.put(
        `${API_URL}/api/v1/inventory/item`,
        {
          productId,
          // locationId will be resolved by backend from user context
          quantity: editingItem.quantity
            ? parseInt(editingItem.quantity, 10)
            : currentItem?.quantity || 0,
          reorderPoint: editingItem.reorderPoint
            ? parseInt(editingItem.reorderPoint, 10)
            : currentItem?.reorderPoint || undefined,
          costCents,
          salesPriceCents,
        },
        { headers: { Authorization: `Bearer ${accessToken}` } },
      );

      toast.success("Inventory item updated successfully");
      setEditingItem(null);
      loadInventory();
    } catch (error: any) {
      console.error("Update error:", error);
      const errorMessage =
        error.response?.data?.message ||
        error.message ||
        "Failed to update inventory item";
      toast.error(errorMessage);
    }
  };

  // Load inventory on mount
  useEffect(() => {
    if (user && accessToken) {
      loadInventory();
    }
  }, [user, accessToken, loadInventory]);

  // Auto-refresh when page comes into focus (e.g., after creating inventory elsewhere)
  useEffect(() => {
    const handleVisibilityChange = () => {
      if (document.visibilityState === "visible" && user && accessToken) {
        loadInventory();
      }
    };

    const handleFocus = () => {
      if (user && accessToken) {
        loadInventory();
      }
    };

    document.addEventListener("visibilitychange", handleVisibilityChange);
    window.addEventListener("focus", handleFocus);

    return () => {
      document.removeEventListener("visibilitychange", handleVisibilityChange);
      window.removeEventListener("focus", handleFocus);
    };
  }, [user, accessToken, loadInventory]);

  return (
    <div className="theme-background min-h-screen w-full overflow-x-hidden">
      <div className="relative mx-auto w-full max-w-7xl space-y-4 sm:space-y-6 px-3 sm:px-4 lg:px-6 py-4 sm:py-6 lg:py-10">
        <div className="theme-card flex flex-col gap-4 sm:gap-6 rounded-xl sm:rounded-2xl lg:rounded-3xl border p-4 sm:p-5 lg:p-6 backdrop-blur-xl md:flex-row md:items-center md:justify-between">
          <div className="flex items-start gap-3 sm:gap-4 min-w-0">
            <BrandMark
              size={40}
              backgroundClassName="bg-white/90 dark:bg-white/10"
              className="ring-1 ring-slate-200/40 dark:ring-white/10 flex-shrink-0 sm:w-[56px] sm:h-[56px]"
            />
            <div className="min-w-0 flex-1">
              <p className="theme-text-secondary text-[10px] sm:text-xs uppercase tracking-[0.35em]">
                Inventory
              </p>
              <h1 className="theme-text-primary text-xl sm:text-2xl lg:text-3xl font-semibold tracking-tight">
                Inventory Management
              </h1>
              <p className="theme-text-secondary text-xs sm:text-sm">
                Store: {effectiveLocationId || user?.locationId || "Loading..."}
                {!user?.locationId && effectiveLocationId && (
                  <span className="ml-1 sm:ml-2 text-[10px] sm:text-xs text-amber-400">
                    (Using tenant's first location)
                  </span>
                )}
              </p>
            </div>
          </div>
          <div className="flex flex-wrap items-center gap-2 sm:gap-3">
            <Link
              to="/checkout"
              className="theme-chip inline-flex items-center gap-1.5 sm:gap-2 rounded-full border px-3 sm:px-4 lg:px-5 py-1.5 sm:py-2 text-xs sm:text-sm font-semibold transition hover:border-emerald-300/60 hover:text-emerald-100 touch-manipulation"
            >
              Checkout
            </Link>
            <button
              onClick={logout}
              className="inline-flex items-center gap-1.5 sm:gap-2 rounded-full bg-gradient-to-r from-rose-400 via-pink-500 to-rose-500 px-3 sm:px-4 lg:px-5 py-1.5 sm:py-2 text-xs sm:text-sm font-semibold text-white shadow-[0_20px_45px_-25px_rgba(244,114,182,0.7)] transition hover:shadow-[0_26px_55px_-20px_rgba(244,114,182,0.85)] touch-manipulation"
            >
              Logout
            </button>
            <ThemeToggle />
          </div>
        </div>

        {/* Scanner */}
        <div className="theme-card rounded-xl sm:rounded-2xl lg:rounded-3xl border p-4 sm:p-5 lg:p-6 backdrop-blur-xl">
          <BarcodeScanner onScan={handleScan} />
        </div>

        {/* Registered Devices */}
        <ScannerDeviceList />

        {/* Adjust Inventory Form */}
        {selectedProduct && (
          <div className="theme-card rounded-3xl border p-6 backdrop-blur-xl">
            <h2 className="theme-text-primary text-xl font-semibold mb-4">
              Adjust Inventory
            </h2>
            <div className="space-y-4">
              <div>
                <p className="theme-text-primary font-semibold">
                  {selectedProduct.name}
                </p>
                <p className="theme-text-secondary text-sm">
                  SKU: {selectedProduct.sku}
                </p>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="theme-text-secondary block text-sm font-medium mb-2">
                    Adjustment Type
                  </label>
                  <select
                    value={adjustType}
                    onChange={(e) =>
                      setAdjustType(e.target.value as "adjust" | "received")
                    }
                    className="w-full rounded-2xl border border-white/15 bg-transparent px-4 py-3 text-sm font-medium text-current outline-none focus:border-emerald-300 focus:ring-2 focus:ring-emerald-300/40"
                  >
                    <option value="adjust">Manual Adjustment</option>
                    <option value="received">Stock Received</option>
                  </select>
                </div>
                <div>
                  <label className="theme-text-secondary block text-sm font-medium mb-2">
                    New Quantity
                  </label>
                  <input
                    type="number"
                    value={adjustQuantity}
                    onChange={(e) => setAdjustQuantity(e.target.value)}
                    className="w-full rounded-2xl border border-white/15 bg-transparent px-4 py-3 text-sm font-medium text-current outline-none focus:border-emerald-300 focus:ring-2 focus:ring-emerald-300/40"
                    placeholder="Enter quantity"
                  />
                </div>
              </div>
              <div className="flex gap-4">
                <button
                  onClick={handleAdjustInventory}
                  className="inline-flex items-center justify-center rounded-full bg-gradient-to-r from-emerald-400 via-emerald-500 to-teal-500 px-6 py-2.5 text-sm font-semibold text-emerald-950 shadow-[0_20px_45px_-25px_rgba(16,185,129,0.7)] transition hover:shadow-[0_24px_55px_-22px_rgba(16,185,129,0.8)]"
                >
                  Update Inventory
                </button>
                <button
                  onClick={() => {
                    setSelectedProduct(null);
                    setAdjustQuantity("");
                  }}
                  className="theme-chip rounded-full border px-5 py-2 text-sm font-semibold hover:border-white/25"
                >
                  Cancel
                </button>
              </div>
            </div>
          </div>
        )}

        {/* Inventory List */}
        <div className="theme-card rounded-3xl border p-0 backdrop-blur-xl">
          <div className="flex items-center justify-between border-b border-white/10 px-6 py-4">
            <h2 className="theme-text-primary text-xl font-semibold">
              Current Inventory
            </h2>
            <button
              onClick={loadInventory}
              className="theme-chip rounded-full border px-4 py-2 text-xs font-semibold hover:border-sky-300/60 hover:text-sky-100"
            >
              Refresh
            </button>
          </div>
          {hasMissingProducts && (
            <div className="px-6 py-4 text-xs font-semibold uppercase tracking-[0.3em] text-amber-300">
              Some inventory items reference deleted or missing products.
              Quantities remain but you may need to recreate the product to
              restore the relationship.
            </div>
          )}

          {loading ? (
            <div className="p-8 text-center">
              <div className="mx-auto h-12 w-12 animate-spin rounded-full border-b-2 border-sky-400"></div>
              <p className="theme-text-secondary mt-4 text-sm">
                Loading inventory...
              </p>
            </div>
          ) : (
            <div className="table-responsive overflow-x-auto -webkit-overflow-scrolling-touch">
              <table className="w-full min-w-[800px] sm:min-w-0">
                <thead className="bg-white/5">
                  <tr>
                    <th className="px-6 py-3 text-left text-xs font-semibold uppercase tracking-[0.2em] text-slate-300">
                      Product
                    </th>
                    <th className="px-6 py-3 text-left text-xs font-semibold uppercase tracking-[0.2em] text-slate-300">
                      SKU
                    </th>
                    <th className="px-6 py-3 text-left text-xs font-semibold uppercase tracking-[0.2em] text-slate-300">
                      Barcode
                    </th>
                    <th className="px-6 py-3 text-left text-xs font-semibold uppercase tracking-[0.2em] text-slate-300">
                      Quantity
                    </th>
                    <th className="px-6 py-3 text-left text-xs font-semibold uppercase tracking-[0.2em] text-slate-300">
                      Reorder Point
                    </th>
                    <th className="px-6 py-3 text-left text-xs font-semibold uppercase tracking-[0.2em] text-slate-300">
                      Cost Price
                    </th>
                    <th className="px-6 py-3 text-left text-xs font-semibold uppercase tracking-[0.2em] text-slate-300">
                      Sales Price
                    </th>
                    <th className="px-6 py-3 text-left text-xs font-semibold uppercase tracking-[0.2em] text-slate-300">
                      Actions
                    </th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-white/10">
                  {inventory.map((item) => (
                    <tr key={item.id} className="hover:bg-white/5 transition">
                      <td className="px-6 py-4 whitespace-nowrap font-medium theme-text-primary">
                        <div className="flex flex-col gap-0.5">
                          <span
                            className={`${item.isProductMissing ? "text-amber-300" : ""}`}
                          >
                            {item.product.name}
                          </span>
                          {item.isProductMissing && (
                            <span className="text-xs uppercase tracking-[0.2em] text-amber-400">
                              Product record missing — recreate to sync
                            </span>
                          )}
                        </div>
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap theme-text-secondary">
                        {item.product.sku}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap theme-text-secondary font-mono text-sm">
                        {item.product.barcode || "—"}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap">
                        {editingItem?.productId === item.productId ? (
                          <input
                            type="number"
                            step="1"
                            min="0"
                            value={editingItem.quantity}
                            onChange={(e) =>
                              setEditingItem({
                                ...editingItem,
                                quantity: e.target.value,
                              })
                            }
                            className="w-24 rounded-lg border-2 border-emerald-400/60 bg-emerald-500/20 px-3 py-2 text-sm font-medium theme-text-primary focus:border-emerald-400 focus:outline-none focus:ring-2 focus:ring-emerald-400/50"
                            placeholder="0"
                          />
                        ) : (
                          <span
                            className={`font-bold ${item.quantity <= (item.reorderPoint || 0) ? "text-red-600" : "text-green-600"}`}
                          >
                            {item.quantity}
                          </span>
                        )}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap theme-text-secondary">
                        {editingItem?.productId === item.productId ? (
                          <input
                            type="number"
                            step="1"
                            min="0"
                            value={editingItem.reorderPoint}
                            onChange={(e) =>
                              setEditingItem({
                                ...editingItem,
                                reorderPoint: e.target.value,
                              })
                            }
                            className="w-24 rounded-lg border-2 border-emerald-400/60 bg-emerald-500/20 px-3 py-2 text-sm font-medium theme-text-primary focus:border-emerald-400 focus:outline-none focus:ring-2 focus:ring-emerald-400/50"
                            placeholder="0"
                          />
                        ) : (
                          <span>{item.reorderPoint || "—"}</span>
                        )}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap theme-text-secondary">
                        {editingItem?.productId === item.productId ? (
                          <input
                            type="number"
                            step="0.01"
                            min="0"
                            value={editingItem.costCents}
                            onChange={(e) =>
                              setEditingItem({
                                ...editingItem,
                                costCents: e.target.value,
                              })
                            }
                            className="w-28 rounded-lg border-2 border-emerald-400/60 bg-emerald-500/20 px-3 py-2 text-sm font-medium theme-text-primary focus:border-emerald-400 focus:outline-none focus:ring-2 focus:ring-emerald-400/50"
                            placeholder="0.00"
                            required
                          />
                        ) : (
                          <span>
                            ₦
                            {item.costCents
                              ? (item.costCents / 100).toFixed(2)
                              : "—"}
                          </span>
                        )}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap theme-text-primary font-semibold">
                        {editingItem?.productId === item.productId ? (
                          <input
                            type="number"
                            step="0.01"
                            min="0"
                            value={editingItem.salesPriceCents}
                            onChange={(e) =>
                              setEditingItem({
                                ...editingItem,
                                salesPriceCents: e.target.value,
                              })
                            }
                            className="w-28 rounded-lg border-2 border-emerald-400/60 bg-emerald-500/20 px-3 py-2 text-sm font-medium theme-text-primary focus:border-emerald-400 focus:outline-none focus:ring-2 focus:ring-emerald-400/50"
                            placeholder="0.00"
                            required
                          />
                        ) : (
                          <span>
                            ₦
                            {item.salesPriceCents
                              ? (item.salesPriceCents / 100).toFixed(2)
                              : item.product.priceCents
                                ? (item.product.priceCents / 100).toFixed(2)
                                : "—"}
                          </span>
                        )}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap">
                        {editingItem?.productId === item.productId ? (
                          <div className="flex gap-2">
                            <button
                              onClick={() => handleUpdateItem(item.productId)}
                              className="rounded-lg border border-emerald-400/40 bg-emerald-500/15 px-3 py-1.5 text-xs font-semibold text-emerald-200 transition hover:bg-emerald-500/25 flex items-center gap-1"
                              title="Update all changes"
                            >
                              <span>✓</span>
                              Update
                            </button>
                            <button
                              onClick={() => setEditingItem(null)}
                              className="rounded-lg border border-white/20 bg-white/5 px-3 py-1.5 text-xs font-semibold text-white/70 transition hover:bg-white/10"
                              title="Cancel editing"
                            >
                              Cancel
                            </button>
                          </div>
                        ) : (
                          <button
                            onClick={() =>
                              setEditingItem({
                                productId: item.productId,
                                quantity: item.quantity.toString(),
                                reorderPoint: item.reorderPoint
                                  ? item.reorderPoint.toString()
                                  : "",
                                costCents: item.costCents
                                  ? (item.costCents / 100).toFixed(2)
                                  : "",
                                salesPriceCents: item.salesPriceCents
                                  ? (item.salesPriceCents / 100).toFixed(2)
                                  : item.product.priceCents
                                    ? (item.product.priceCents / 100).toFixed(2)
                                    : "",
                              })
                            }
                            className="inline-flex items-center justify-center gap-2 rounded-lg bg-gradient-to-r from-blue-500 to-blue-600 px-4 py-2.5 text-sm font-bold text-white shadow-lg transition-all hover:from-blue-600 hover:to-blue-700 hover:shadow-xl hover:scale-105 active:scale-95"
                            title="Edit inventory item - Click to edit quantity, reorder point, cost price, and selling price"
                          >
                            <svg
                              xmlns="http://www.w3.org/2000/svg"
                              className="h-5 w-5"
                              fill="none"
                              viewBox="0 0 24 24"
                              stroke="currentColor"
                              strokeWidth={2.5}
                            >
                              <path
                                strokeLinecap="round"
                                strokeLinejoin="round"
                                d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z"
                              />
                            </svg>
                            <span className="font-semibold">Edit</span>
                          </button>
                        )}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}
